(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0034.js"] = [{"id":"poem-de1d484be7ec140d4fe79289","title":"陪杭州郡使䜩西湖亭","author":"张祜","dynasty":"唐","verses":["小亭移宴近云端，十里山图马上看。","青壁远光凌鸟峻，碧湖深影鍳人寒。","诗成病愈生犀角，酒引娇娃活牡丹。","归去不须愁暮雨，高唐神女属仙坛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8a439117-3395-4903-b072-f374ad69293b","tags":["西湖"]},{"id":"poem-de1d5a364b29ea5e35f4b1e6","title":"新主簿沈机惠棋局","author":"米芾","dynasty":"宋","verses":["纵横世路久无猜，布劫争先岂系怀。","与我一枰撩万绪，操戈信是逐生来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2ea8cda8-65ab-4817-98fa-43178860ef49","tags":[]},{"id":"poem-de1ef998fb5ba8bcfe33b1af","title":"江城子·片帆初落甬勾东","author":"史浩","dynasty":"宋","verses":["片帆初落甬勾东。","碧湖空。","满汀风。","回首一川，银浪飐孤篷。","且驾两椽烟雨里，凭曲槛，浥空蒙。","闲移拄杖上晴峰。","莫匆匆。","伴冥鸿。","笑指家山，苹叶藕花中。","脚力倦时呼小艇，归棹稳，月朦胧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-90","tags":[]},{"id":"poem-de290df41da23009228ae7ac","title":"以端谿砚酬张员外水精珠兼和来篇","author":"徐铉","dynasty":"宋","verses":["请以端谿润，酬君水玉明。","方圆虽异器，功用信俱呈。","自得山川秀，能分日月精。","巾箱各珍重，所贵在交情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ec72560b-3fbf-4303-8171-d7e198e18519","tags":[]},{"id":"poem-de29f44ae2db558e1446f222","title":"莲子","author":"林敏修","dynasty":"宋","verses":["落尽红裳翠的生，甘泉金铸马蹄轻。","中心有意君知否，半是湘妃泪点成。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0adefaa5-f245-4028-a238-cd268a3cf404","tags":[]},{"id":"poem-de375bf56c27433279a4b44d","title":"申伯和篇举叔易自代叔诗复推申伯要之二子皆当由此科取重名于世恨吾资妄髙不得偕二子鸣跃其间复次前韵以兼勉之","author":"李纲","dynasty":"宋","verses":["古来豪杰收殊科，眇然鸾凤亦可罗。","汉唐选举最为盛，我宋得士良已多。","危言切论动天壤，陆离剑佩冠巍峨。","至今凛凛有生气，岂与草木同销磨。","自从罢举乐软美，驯致黠虏窥关河。","翠华两宫狩沙漠，叠鼓万里翻鲸波。","睿明感愤复旧制，欲起士气宁兵戈。","多材好学如二子，辞此其奈制举何。","青钱万选当万中，善射不复言公他。","勉将忠谠助休运，嗟我老矣真蹉跎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5e0d9a60-3384-4508-b79a-0248c623627d","tags":[]},{"id":"poem-de3c31f59b3291433801d5ed","title":"郊庙歌辞 晋朝飨乐章 群臣酒行歌 二","author":"不详","dynasty":"唐","verses":["万国咸归禹，千官共祝尧。","拜恩瞻凤扆，倾耳听云韶。","运启金行远，时和玉烛调。","酒酣齐抃舞，同贺圣明朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7f4d2f20-a7ac-4310-b2d5-3fb079011272","tags":[]},{"id":"poem-de42bedc3260fa9cf6f84942","title":"赠杨炼师","author":"鲍溶","dynasty":"唐","verses":["紫烟衣上绣春云，清隐山书小篆文。","明月在天将凤管，夜深吹向玉晨君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c7aec29c-9275-402e-ac74-7f9e29c3cad4","tags":[]},{"id":"poem-de453edeb935a3552c2ef636","title":"郊庙歌辞 武后大享拜洛乐章 归和","author":"不详","dynasty":"唐","verses":["言旋云洞兮蹑烟途，永宁中宇兮安下都。","包涵动植兮顺荣枯，长贻宝贶兮赞璇图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-903b1584-af9d-4ac6-a017-4df18161929c","tags":[]},{"id":"poem-de46bc24b0dfcac898aad3e9","title":"女冠子","author":"无名氏《张协状元》","dynasty":"元","verses":["位迁极品，簪缨势象板派。","家传诗礼，门排朱紫。","更兼亲戚，尽皆豪迈。","当朝为宰执，一女笄年，未及婚嫁。","这些儿愁闷，镇在心头，无缘可解。","(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2536","tags":[]},{"id":"poem-de48bc73e6f1e9ea806c9e4a","title":"同诸公登慈恩寺浮图","author":"高适","dynasty":"唐","verses":["香界泯群有，浮图岂诸相。","登临骇孤高，披拂欣大壮。","言是羽翼生，迥出虚空上。","顿疑身世别，乃觉形神王。","宫阙皆户前，山河尽簷向。","秋风昨夜至，秦塞多清旷。","千里何苍苍，五陵郁相望。","盛时慙阮步，末宦知周防。","输效独无因，斯焉可游放。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-a491ab1b-43b6-4757-b3bb-9e984de2b5d9","tags":[]},{"id":"poem-de5406e98afbd6a11398d0af","title":"般","author":"佚名","dynasty":"先秦","verses":["于皇时周！陟其高山，嶞山乔岳，允犹翕河。敷天之下，裒时之对。时周之命。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-295","tags":[]},{"id":"poem-de574c4a6b863772b8c08645","title":"八声甘州·渺空烟四远","author":"吴文英","dynasty":"宋","verses":["渺空烟四远，是何年、青天坠长星。","幻苍崖云树，名娃金屋，残霸宫城。","箭径酸风射眼，腻水染花腥。","时靸双鸳响，廊叶秋声。","宫里吴王沈醉，倩五湖倦客，独钓醒醒。","问苍波无语，华发奈山青。","水涵空、阑干高处，送乱鸦、斜日落渔汀。","连呼酒，上琴台去，秋与云平。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-81","tags":["宋词三百首"]},{"id":"poem-de61701e107b72ba5ca0a203","title":"石鹤","author":"李翔","dynasty":"唐","verses":["白石孤标逸鹤形，古人随类巧安名。","岩花落处见朱顶，夜雨来时闻唳声。","辽海未曾重寄语，缑山今更请宽程。","若教卫懿如今在，也遣轩车到此迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f583912d-b45d-4a3b-9299-f14eec0b33a8","tags":[]},{"id":"poem-de629563c3b67229cd166d2f","title":"浣溪沙·十里西畴熟稻香","author":"范成大","dynasty":"宋","verses":["十里西畴熟稻香。","槿花篱落竹丝长。","垂垂山果挂青黄。","浓雾知秋晨气润，薄云遮日午阴凉。","不须飞盖护戎装。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-259","tags":[]},{"id":"poem-de645357afe400128befe878","title":"偈颂（幷序○序为南岳齐己撰） 十七","author":"居遁","dynasty":"唐","verses":["何事朝愁与暮愁，少年不学老还羞。","骊珠不是骊龙惜，自是时人不解求。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8539d46f-8577-4235-af71-42f874977ef3","tags":["衡山"]},{"id":"poem-de6696d496289b6c6de7608a","title":"如梦令·正是辘轳金井","author":"纳兰性德","dynasty":"清","verses":["正是辘轳金井，满砌落花红冷。","蓦地一相逢，心事眼波难定。","谁省，谁省。","从此簟纹灯影。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-29","tags":[]},{"id":"poem-de67eed4e55a5298864ade53","title":"答李浣","author":"韦应物","dynasty":"唐","verses":["林中观易罢，溪上对鸥闲。","楚俗饶词客，何人最往还。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答李浣","tags":[]},{"id":"poem-de6e2a1e7004c3d0d29e97ee","title":"点绛唇·征骑初停","author":"周邦彦","dynasty":"宋","verses":["征骑初停，酒行莫放离歌举。","柳汀莲浦。","看尽江南路。","苦恨斜阳，冉冉催人去。","空回顾。","淡烟横素。","不见扬鞭处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-401","tags":[]},{"id":"poem-de6f33c7475cecef2138e12e","title":"好姐姐","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["念奴流血满指，奈独自要坟成无计，深感老天暗中相护持。","(合)坟成矣。","葬了二亲寻夫婿，改换衣装往帝畿。","(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5147","tags":[]},{"id":"poem-de73ce3aaff0716244baa330","title":"先寄左军语道","author":"刘跂","dynasty":"宋","verses":["已喜仲容连骑去，更思小陆度山来。","赋槐白士愁颜甚，唤取溪傍一笑开。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2754860e-e43a-43b0-a925-be94182b0b3f","tags":[]},{"id":"poem-de7934ae18ad636945e8ad08","title":"读经","author":"孟郊","dynasty":"唐","verses":["垂老抱佛脚，教妻读黄经。","经黄名小品，一纸千明星。","曾读大般若，细感肸蚃听。","当时把斋中，方寸抱万灵。","忽复入长安，蹴踏日月宁。","老方却归来，收拾可丁丁。","拂拭尘几案，开函就孤亭。","儒书难借索，僧签饶芳馨。","驿驿不开手，铿铿闻异铃。","得善如焚香，去恶如脱腥。","安得颜子耳，曾未如此听。","听之何有言，德教贵有形。","何言中国外，有国如海萍。","海萍国教异，天声各泠泠。","安排未定时，心火竞荧荧。","将如庶几者，声尽形元冥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ba1c1ea7-01bf-40cb-b6a1-78b8188df5b3","tags":[]},{"id":"poem-de79619eb2eecfcb122cb0b5","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["今君转下山，有一家。","朱门两扇屋虽破，是鸳鸯瓦。","(生)又怎知它着我？谢得尊神呵周全我，今宵免得心肠挂。","(合同前)(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2491","tags":[]},{"id":"poem-de8a299a1f87215eda7bcf70","title":"省题诗二十一首 寒雨滴空阶","author":"王棨","dynasty":"唐","verses":["霏霏飘永夜，滴滴落空阶。","自有路歧恨，那堪离别怀。","簷前声乍碎，枕畔梦全乖。","远与岩泉杂，微将漏水谐。","天涯思旧友，法上忆闲斋。","坐到空庭晓，残云带石崖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9b924327-8d39-4fe3-a3d2-ed0ec225571c","tags":[]},{"id":"poem-de9618a3ead800e130ce3b39","title":"浪淘沙·蛮歌豆蔻北人愁","author":"皇甫松","dynasty":"唐","verses":["蛮歌豆蔻北人愁，蒲雨杉风野艇秋。","浪起䴔䴖眠不得，寒沙细细入江流。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-19","tags":[]},{"id":"poem-de96c06e85aa34e946997bf8","title":"别墅","author":"李山甫","dynasty":"唐","verses":["此地可求息，开门足野情。","窗明雨初歇，日落风更清。","苍藓槎根匝，碧烟水面生。","玩奇心自乐，暑月听蝉声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3650d400-b87b-405e-8235-45f67cbc43f1","tags":[]},{"id":"poem-de9bb4a69227d501c438c6fd","title":"水调歌头·江水自石纽","author":"魏了翁","dynasty":"宋","verses":["江水自石纽，灌口怒腾辉。","便如黑水北出，迤逦到三危。","百尺长虹夭矫，两岸苍龙偃蹇，翠碧互因依。","古树百夫长，修竹万竿旗。","画堂开，风与月，巧相随。","史君领客行乐，旌纛立披披。","慨想二江遗迹，更起三闾忠愤，此日最为宜。","推本美功意，禹甸六章诗。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-421","tags":[]},{"id":"poem-de9c79005eb3dfb3a216b690","title":"重题","author":"李德裕","dynasty":"唐","verses":["晚日临寒渚，微风发櫂讴。","凤池波自阔，鱼水运难留。","亭古思宏栋，川长忆夜舟。","想公高世志，祗似冶城游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b63a96f9-e226-4ef7-a0fb-6970d0f8465e","tags":[]},{"id":"poem-de9fbd7e0b42b205e3977930","title":"书怀","author":"刘幽求","dynasty":"唐","verses":["心为明时尽，君门尚不容。","田园迷径路，归去欲何从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-25de451b-7c61-45d1-8291-061bdfc5e166","tags":[]},{"id":"poem-dea6dcb392790dfbbd41f9cc","title":"古别离","author":"聂夷中","dynasty":"唐","verses":["欲别牵郎衣，问郎游何处。","不恨归日迟，莫向临邛去。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-02c52bf9-7672-44a1-a618-92b26b91fde1","tags":["送别","女子","情郎"]},{"id":"poem-dead6f4ce11bc435aef33608","title":"青玉案·年年社日停针线","author":"无名氏","dynasty":"宋","verses":["年年社日停针线。","怎忍见、双飞燕。","今日江城春已半。","一身犹在，乱山深处，寂寞溪桥畔。","春衫著破谁针线。","点点行行泪痕满。","落日解鞍芳草岸。","花无人戴，酒无人劝，醉也无人管。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-274","tags":["宋词三百首"]},{"id":"poem-deba713527669d3791fcaee0","title":"玉团儿·妍姿艳态腰如束","author":"周邦彦","dynasty":"宋","verses":["妍姿艳态腰如束。","笑无限、桃粗杏俗。","玉体横陈，云鬟斜坠，春睡还熟。","夕阳斗转阑干曲。","乍醉起、馀霞衬肉。","搦粉搓酥，剪云裁雾，比并不足。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-484","tags":[]},{"id":"poem-debded5bb42ab305105aad9a","title":"寻天目徐君","author":"皎然","dynasty":"唐","verses":["常见仙翁变姓名，岂知松子号初平。","逢人不道往来处，卖药还将鸡犬行。","独鹤天边俱得性，浮云世上共无情。","三花落地君犹在，笑抚安期昨日生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-54f33f90-b7d7-43e1-a340-33167ea05bcf","tags":[]},{"id":"poem-dec54a257dfa1726d2144f1b","title":"闻春雷","author":"司空曙","dynasty":"唐","verses":["水国春雷早，阗阗若众车。","自怜迁逐者，犹滞蛰藏余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d2f4fe85-03f9-467c-a6f9-8d9a435fdbf2","tags":[]},{"id":"poem-dec88633e95ed0874af7e687","title":"漫书","author":"司空图","dynasty":"唐","verses":["乐退安贫知是分，成家报国亦何惭。","到还僧院心期在，瑟瑟澄鲜百丈潭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-aa67069a-e4c0-4249-948b-a2e29418896e","tags":[]},{"id":"poem-decfeda361d81bc340997f6d","title":"谏堂山","author":"陈岩","dynasty":"宋","verses":["茸茸莎草褭风长，二百年前一谏堂。","旧地几番新地主，谏堂名字愈辉光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e322b1db-6c80-4a8c-9818-388dc1ba3e84","tags":[]},{"id":"poem-ded045f16caa66c23869341f","title":"羔裘","author":"佚名","dynasty":"先秦","verses":["羔裘豹祛，自我人居居。岂无他人？维子之故。","羔裘豹褎，自我人究究。岂无他人？维子之好。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-119","tags":[]},{"id":"poem-ded23756e62a8058da61e83e","title":"睡起","author":"赵文","dynasty":"宋","verses":["小窗午热倦如柳，睡起雨来江浪声。","快意百年浑似此，不须浮海觅长生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-aa1cc385-2e51-48c3-84c2-91dd75b6cfbd","tags":[]},{"id":"poem-ded60c6732d93e2cf15b071d","title":"女冠子·凤楼琪树","author":"鹿虔扆","dynasty":"五代","verses":["凤楼琪树，惆怅刘郎一去，正春深。","洞里愁空结，人间信莫寻。","竹疏斋殿迥，松密醮坛阴。","倚云低首望，可知心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-15","tags":[]},{"id":"poem-dedc26c3cb43fb0a4ed58393","title":"春日登大悲阁（四言回文）","author":"钱惟治","dynasty":"唐","verses":["春城满望，晓阁闲登。","尘销霁景，定出真僧。","人怀远思，槛凭危层。","因圆果证，胜境斯兴。","（均见明梁桥《冰川诗式》卷二。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-66b52dc2-f6e8-4fee-a09c-effbb5444e02","tags":[]},{"id":"poem-dee284477b30d8b6499d77d0","title":"幸梨园亭观打毬应制","author":"沈佺期","dynasty":"唐","verses":["今春芳苑游，接武上琼楼。","宛转萦香骑，飘飖拂画毬。","俯身迎未落，回辔逐傍流。","秖为看花鸟，时时误失筹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-70585fc1-31c6-4d25-92a0-f8c52cc26957","tags":[]},{"id":"poem-dee459550590623527d8ee0d","title":"咏史诗 玉门关","author":"胡曾","dynasty":"唐","verses":["西戎不敢过天山，定远功成白马闲。","半夜帐中停烛坐，唯思生入玉门关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-338cb62a-f860-440f-bc06-4b0abb422e36","tags":[]},{"id":"poem-dee811c6f1ed5d1bde144fb0","title":"送罗判官还寿州幕","author":"皎然","dynasty":"唐","verses":["君章才五色，知尔得家风。","故里旋归驾，寿春思奉戎。","天寒长蛇伏，飙烈文虎雄。","定颂张征虏，桓桓戡难功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ccc82c46-f8e8-4870-8ec4-07c89144fa67","tags":[]},{"id":"poem-deeb24bc1a28d798acb0d4dd","title":"和前人韵  其一","author":"王柏","dynasty":"宋","verses":["名山终是欠徘徊，小队轻车决意来。","他日相思无觅处，殷勤先赠岭头梅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b2222b34-659c-4fe0-a6d9-742af61c1035","tags":[]},{"id":"poem-def2e3748701bd450dbaea6d","title":"寿昌节赋得红云表夏日","author":"栖白","dynasty":"唐","verses":["景候融融阴气潜，如峰云共火相兼。","霞光捧日登天上，丹彩乘风入殿簷。","行逐赤龙千岁出，明当朱夏万方瞻。","微臣多幸逢佳节，得赋殊祥近御帘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6d2c9460-ed93-442d-a6ce-1c19d0dd3d37","tags":[]},{"id":"poem-def4f6cf74f6bba6ea5e0897","title":"听演师琴","author":"史卫卿","dynasty":"宋","verses":["禅悟却参琴，山高水复深。","七弦手共语，万籁耳无音。","激烈鬼神泪，发挥天地心。","秋风时一曲，怀古更伤今。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-e62b39e6-2910-41e1-a8fb-e87b74fe18a3","tags":[]},{"id":"poem-df13aacfbad330def24d6b91","title":"赏花时","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["憔悴容颜只为你，每日在书房攻甚诗书！(生)闲话且休提，你把这时行的传奇，(旦白)看掌记。","(生连唱)你从头与我再温习。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-303","tags":[]},{"id":"poem-df1f89554b4951db67aeb348","title":"升平词十首 一","author":"薛能","dynasty":"唐","verses":["瑞气遶宫楼，皇居信上游。","远冈连圣祚，平地载神州。","会合皆重译，潺湲近八流。","中兴岂假问，据此自千秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-77d2f6f6-15d2-4d1a-a3d3-e3a61f4cf506","tags":[]},{"id":"poem-df2d88bd3d479d9c59f841d9","title":"垂丝钓·缕金翠羽","author":"周邦彦","dynasty":"宋","verses":["缕金翠羽。","妆成才见眉妩。","倦倚绣帘，看舞风絮。","愁几许。","寄凤丝雁柱。","春将暮。","向层城苑路。","钿车似水，时时花径相遇。","旧游伴侣。","还到曾来处。","门掩风和雨。","梁间燕语。","问那人在否。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-389","tags":[]},{"id":"poem-df2dd0146b905162e9d81b65","title":"虞美人·残灯风灭炉烟冷","author":"纳兰性德","dynasty":"清","verses":["残灯风灭炉烟冷，相伴唯孤影。","判教狼藉醉清樽，为问世间醒眼是何人。","难逢易散花间酒，饮罢空搔首。","闲愁总付醉来眠，只恐醒时依旧到樽前。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-107","tags":[]},{"id":"poem-df382d29529862625713bc0a","title":"送人征蛮","author":"贯休","dynasty":"唐","verses":["七纵七擒处，君行事可攀。","亦知磨一劒，不独定诸蛮。","树尽低铜柱，潮常沸火山。","名须麟阁上，好去及瓜还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-517cc330-aad1-4218-bf53-27cd8314a62f","tags":[]},{"id":"poem-df3bf519bf24da7faa73b5c2","title":"采桑子·海天谁放冰轮满","author":"纳兰性德","dynasty":"清","verses":["海天谁放冰轮满，惆怅离情。","莫说离情，但值良宵总泪零。","只应碧落重相见，那是今生。","可奈今生，刚作愁时又忆卿。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-92","tags":[]},{"id":"poem-df4260a5a084d21c55dd4d0e","title":"早春旬假独直寄江舍人","author":"徐铉","dynasty":"宋","verses":["省署皆归沐，西垣公事稀。","咏诗前砌立，听漏向申归。","远思风醒酒，余寒雨湿衣。","春光已堪探，芝盖共谁飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-23bec8e0-a1b3-43ae-86a6-c21eb739c0c5","tags":[]},{"id":"poem-df54ab3477b7feab58a61d74","title":"渔家傲·郊外春和宜散步","author":"米友仁","dynasty":"宋","verses":["郊外春和宜散步。","百花枝上初凝露。","福地神仙多外府。","藏奇趣。","幽寻历遍溪边路。","薄宦浮家无定处。","萍飘梗泛前人语。","与子未须乡国去。","来同住。","且看群岫烟中雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-56","tags":[]},{"id":"poem-df68c73bdfc5fb8710bb3024","title":"高阳台·残雪庭阴","author":"王沂孙","dynasty":"宋","verses":["残雪庭阴，轻寒帘影，霏霏玉管春葭。","小帖金泥，不知春在谁家。","相思一夜窗前梦，奈个人、水隔天遮。","但凄然，满树幽香，满地横斜。","江南自是离愁苦，况游骢古道，归雁平沙。","怎得银笺，殷勤与说年华。","如今处处生芳草，纵凭高、不见天涯。","更消他，几度东风，几度飞花。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-251","tags":["宋词三百首"]},{"id":"poem-df75a07ab08c4394c18ec2dc","title":"永遇乐·璧月初晴","author":"刘辰翁","dynasty":"宋","verses":["璧月初晴，黛云远澹，春事谁主。","禁苑娇寒，湖堤倦暖，前度遽如许。","香尘暗陌，华灯明昼，长是懒携手去。","谁知道，断烟禁夜，满城似愁风雨。","宣和旧日，临安南渡，芳景犹自如故。","缃帙流离，风鬟三五，能赋词最苦。","江南无路，州今夜，此苦又谁知否。","空相对，残无寐，满村社鼓。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-91","tags":["宋词三百首"]},{"id":"poem-df7616669a58f764da85029b","title":"僧舍假山","author":"米芾","dynasty":"宋","verses":["玉峰高爱搀天碧，过眼云关无处觅。","才将呀豁向疏窗，已见峰棱翻瘦脊。","明月照出溪中水，清风扫遍岩边石。","悬崖绝磴疑可擥，白露苍烟俱咫尺。","天阴未彻山阴寒，雨声欲绝泉声干。","须知物理有真妄，岂识道眼无殊观。","万象森严掌握内，大块俯仰毫芒间。","抽身更洗清浄足，探历幽深非所难。","山僧作山真有以，诗人吟诗从此始。","意教妙手发天悭，戏取神功当众美。","君不见浣花野老深结庐，白盐赤甲龙虎趋。","清吟醉赏左右足，当时应笑秦鞭驱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f6943737-91f5-4ca4-9e07-1df69511b29a","tags":[]},{"id":"poem-df99d6d14fecb5eb675819f7","title":"荅僧澈","author":"知玄","dynasty":"唐","verses":["观君法苑思冲虚，使我真乘刃有余。","若使龙光时可待，应怜僧肇论成初。","五车外典知谁敌，九趣多才恐不如。","萧寺讲轩横淡荡，帝乡云树正扶疎。","几生曾得阇瑜意，今日堪将贝叶书。","一振微言冠千古，何人执卷问吾庐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-26806e16-f95a-4ea8-9162-15b848082b8e","tags":[]},{"id":"poem-dfa569da8a3fb2c0ab47b98b","title":"干戈","author":"王中","dynasty":"宋","verses":["干戈未定欲何之，一事无成两鬓丝。","踪迹大纲王粲传，情怀小样杜陵诗。","鹡鸰音断人千里，乌鹊巢寒月一枝。","安得中山千日酒，酩然直到太平时。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-干戈","tags":[]},{"id":"poem-dfa8f68a6cc1c3351a0a280c","title":"杂诗","author":"崔湜","dynasty":"唐","verses":["鹊巢恶木巅，常窘一枝息；宁知猗（椅）[一]（原卷作「椅」）梧凤，亦欲此栖宿！喈喈多好音，矫矫奋轻翼，上林岂不成，（蒋礼鸿〖简称「蒋」〗、项楚〖简称「项」〗皆云：「成」当作「茂」。","原卷作「茂」。","）胡为恋幽仄？","处陋仍莫保，居华固陵偪，下流不可居[二]斯言可佩服。","（[一]俞平伯先生云：「『猗梧』当作『椅梧』。","《诗·定之方中》：『椅桐梓漆。","』」[二]刘盼遂先生云：「司马迁《报任少卿书》云：负下未易居，下游多谤议，此合为一句。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-34d12f77-9f60-4527-ba72-162036e2cffc","tags":[]},{"id":"poem-dfb5050ef3b2e5021984f2b8","title":"琵琶引","author":"白居易","dynasty":"唐","verses":["浔阳江头夜送客，枫叶荻花秋索索。","主人下马客在船，举酒欲饮无管弦。","醉不成欢惨将别，别时茫茫江浸月。","忽闻水上琵琶声，主人忘归客不发。","寻声暗问弹者谁，琵琶声停欲语迟。","移船相近邀相见，添酒回灯重开宴。","千呼万唤始出来，犹抱琵琶半遮面。","转轴拨弦三两声，未成曲调先有情。","弦弦掩抑声声思，似诉平生不得意。","低眉信手续续弹，说尽心中无限事。","轻拢慢撚抹复挑，初为霓裳后六幺。","大弦嘈嘈如急雨，小弦切切如私语。","嘈嘈切切错杂弹，大珠小珠落玉盘。","间关莺语花底滑，幽咽泉流水下滩。","水泉冷涩弦疑绝，疑绝不通声暂歇。","别有幽愁暗恨生，此时无声胜有声。","银缾乍破水浆迸，铁骑突出刀枪鸣。","曲终收拨当心画，四弦一声如裂帛。","东舟西舫悄无言，唯见江心秋月白。","沈吟放拨插弦中，整顿衣裳起敛容。","自言本是京城女，家在虾蟇陵下住。","十三学得琵琶成，名蜀教坊第一部。","曲罢曾教善才伏，妆成每被秋娘妬。","五陵年少争缠头，一曲红绡不知数。","钿头云箆击节碎，血色罗帬飜酒污。","今年欢笑复明年，秋月春风等闲度。","弟走从军阿姨死，暮去朝来颜色故。","门前冷落鞍马稀，老大嫁作商人妇。","商人重利轻别离，前月浮梁买茶去。","去来江口守空船，绕船月明江水寒。","夜深忽梦少年事，梦啼妆泪红阑干。","我闻琵琶已叹息，又闻此语重唧唧。","同是天涯沦落人，相逢何必曾相识。","我从去年辞帝京，谪居卧病浔阳城。","浔阳小处无音乐，终岁不闻丝竹声。","住近湓江地低湿，黄芦苦竹绕宅生。","其间旦暮闻何物，杜鹃啼血猨哀鸣。","春江花朝秋月夜，往往取酒还独倾。","岂无山歌与村笛，呕哑嘲哳难为听。","今夜闻君琵琶语，如听仙乐耳暂明。","莫辞更坐弹一曲，为君飜作琵琶行。","感我此言良久立，却坐促弦弦转急。","凄凄不似向前声，满座重闻皆掩泣。","座中泣下谁最多，江州司马青衫湿。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0fb0189c-8ff3-4106-af94-f6d26d528a1d","tags":["唐诗三百首","七言古诗","高中古诗","写人","乐府","三年级下册","愤懑"]},{"id":"poem-dfb5f3407620d833a2ff0d62","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(丑)劫掠金珠个要分，不要分。","肥羊美酒不沾唇，不沾唇。","但愿捉得个多娇女。","将来压寨做大人。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2922","tags":[]},{"id":"poem-dfb8588912c368025dc22918","title":"秦中送李九赴越","author":"高适","dynasty":"唐","verses":["携手望千里，于今将十年。","如何每离别，心事复迍邅。","适越虽有以，出关终耿然。","愁霖不可向，长路或难前。","吴会独行客，山阴秋夜船。","谢家征故事，禹穴访遗编。","镜水君所忆，莼羹余旧便。","归来莫忘此，兼示济江篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b1dacf07-db06-4ed7-bb07-6891a34273c8","tags":[]},{"id":"poem-dfc669b250c0aadb5f21bcbe","title":"赠司勋萧郎中","author":"张子容","dynasty":"唐","verses":["作相开黄阁，为郎奏赤墀。","君臣道合体，父子贵同时。","国以推贤答，家无内举疑。","凤池真水镜，兰省得华滋。","未覩风流日，先闻新赋诗。","江山清谢朓，花木媚丘迟。","吏部来何暮，王言念在兹。","丹青无不可，霖雨亦相期。","昔我投荒处，孤烟望岛夷。","群鸥终日狎，落叶数年悲。","渔父留歌咏，江妃入兴词。","今将献知己，相感勿吾欺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0cf82a91-18a7-4f64-b1c3-c46289755e7b","tags":[]},{"id":"poem-dfc7d9d66251acb2e25660cf","title":"酒泉子·黛愁怨红羞","author":"顾敻","dynasty":"五代","verses":["黛愁怨红羞，掩映画堂春欲暮。","残花微雨隔青楼，思悠悠。","芳菲时节看将度，寂寞无人还独语。","画罗襦，香粉污，不胜愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-14","tags":[]},{"id":"poem-dfc9432149b15c34e29fa0ca","title":"和韩子文五首  其二","author":"曾协","dynasty":"宋","verses":["雪痕尚使石泉润，山色不堪烟雨昏。","见说树头春意动，从头花柳看村村。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-daae49dd-4249-4fd2-9bb5-aa61d436bb8d","tags":[]},{"id":"poem-dfc9872620a1ad970a6bf26b","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["唐太宗是圣明之君，犹且杀建成。","哥哥莫待祸临身，临渴怎生掘井？(生)若非兄弟说着事因，险些儿遭他毒性。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1712","tags":[]},{"id":"poem-dfde3559f4b1890d20ee675b","title":"新水令","author":"无名氏《张协状元》","dynasty":"元","verses":["朔风凛冽云垂地，见长空六花飞坠。","踏雪归来也，仗一点灯儿，伴岑寂。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2498","tags":[]},{"id":"poem-dfe0c89f04c1c39fd540872e","title":"和元晦林间残雪之韵","author":"张栻","dynasty":"宋","verses":["眼中光洁尽琼瑶，未觉鬰蓝宫殿遥。","石壁长林冰筯落，锵然玉佩响层霄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-615837c1-265e-4aeb-96ee-1a47057b4932","tags":[]},{"id":"poem-dfe9ec6fe827e3b6a994386b","title":"题新安国寺","author":"李洞","dynasty":"唐","verses":["佛亦遇艰难，重兴叠废坛。","偃松枝旧折，画竹粉新干。","开讲宫娃听，抛生禁鸟餐。","钟声入帝梦，天竺化长安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-13d229d0-4297-4936-bf0a-bb367ad0ddc9","tags":[]},{"id":"poem-dfeb57722c4c404107b84b46","title":"苦哉远征人","author":"鲍溶","dynasty":"唐","verses":["征人歌古曲，携手上河梁。","李陵死别处，窅杳玄冥乡。","忆昔从此路，连年征鬼方。","久行迷汉历，三死氊衣裳。","百战身且在，微功信难忘。","远承云台议，非势孰敢当。","落日吊李广，白首过河阳。","闲弓失月影，劳劒无龙光。","去日始束发，今来发成霜。","虚名乃闲事，生见父母乡。","掩抑大风歌，裴回少年场。","诚哉古人言，鸟尽良弓藏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-eb262b65-a14b-4bf4-a32d-7a641244f21b","tags":[]},{"id":"poem-dfeed2a7d602bae6db28de2a","title":"双劝酒","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净上］儒冠误身，一言难尽。","为玉莲贱人，常怀方寸。","若得他配合秦晋，那其间燕尔新婚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8164","tags":[]},{"id":"poem-dff27c4f04985cd648d0f2a8","title":"杂曲歌辞 长相思三首 二","author":"李白","dynasty":"唐","verses":["日色已尽花含烟，月明欲素愁不眠。","赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。","此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。","昔日横波目，今成流泪泉。","不信妾肠断，归来看取明镜前。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-caa023cf-9f55-450c-9638-1cf5c0223cc1","tags":["唐诗三百首","思念","乐府"]},{"id":"poem-e00b8e5821476336fb47cbd8","title":"威德方丈桂著花长官赵两山相过","author":"释居简","dynasty":"宋","verses":["举子忙时节，秋庭桂子春。","暂分餐菊伴，来款种花人。","密影窥簷小，繁英趁月新。","发硎盘错外，树下看修轮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8169b0d3-e5e3-4fb4-b228-2b3174cb7245","tags":[]},{"id":"poem-e00e67aca0b11154661e8f0c","title":"山麻客","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)你去渡关津，怕有人盘问，又没个官司文凭路引。","此行何处能安顿？蓦忽地怕有便人，寄取一封平安书信。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2891","tags":[]},{"id":"poem-e011257cdbca912fdb395c1f","title":"偈颂（幷序○序为南岳齐己撰） 八十八","author":"居遁","dynasty":"唐","verses":["一念心清净，莲华处处开。","一华一净土，一土一如来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d58a8163-6d40-4af3-9c1c-c149e5fb3fe0","tags":["衡山"]},{"id":"poem-e0158ed06ab129de951e342e","title":"金莲绕凤楼·绛烛朱笼相随映","author":"赵佶","dynasty":"宋","verses":["绛烛朱笼相随映。","驰绣毂、尘清香衬。","万金光射龙轩莹。","绕端门、瑞雷轻振。","元宵为开圣景。","严敷坐、观灯锡庆。","帝家华英乘春兴。","搴珠帘、望尧瞻舜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-538","tags":[]},{"id":"poem-e01595c9e68f96d22c180bf2","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(旦)溺水自心酸，我婆婆苦万千，堂前继母心不善。","儿夫去远，家尊老年，何日得见王佥判？(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8221","tags":[]},{"id":"poem-e0190ca9faf844a553625c2d","title":"梦天","author":"李贺","dynasty":"唐","verses":["老兔寒蟾泣天色，云楼半开壁斜白。","玉轮轧露湿团光，鸾珮相逢桂香陌。","黄尘清水三山下，更变千年如走马。","遥望齐州九点烟，一泓海水杯中泻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-812cff97-e2ca-447b-abf6-76617a8f77f8","tags":["梦游","月宫","想象","哲理"]},{"id":"poem-e0235a7908a259424c37bdbf","title":"失调名·不是这","author":"沈唐","dynasty":"宋","verses":["不是这，下辈无礼，都缘是我，自家遭逢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-862","tags":[]},{"id":"poem-e02629c5ba72b97fa3eff652","title":"临江仙·用心勤苦是新诗","author":"邢俊臣","dynasty":"宋","verses":["用心勤苦是新诗。","吟安一个字，拈断数茎髭。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-840","tags":[]},{"id":"poem-e0377bfd","title":"村居","author":"高鼎","dynasty":"清","verses":["草长莺飞二月天，拂堤杨柳醉春烟。","儿童散学归来早，忙趁东风放纸鸢。"],"enabled":true,"collection":"历代名篇","source":"高鼎《拙吾诗稿》诗《村居》。","tags":["春日","童趣"]},{"id":"poem-e03b1cd0dd4f390c77cc0ff1","title":"宛陵望月寄沈学士","author":"赵嘏","dynasty":"唐","verses":["一川如画敬亭东，待诏闲游处处同。","天竺山前镜湖畔，何如今日庾楼中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a3e20bc3-b48a-4439-8c12-da9489021df5","tags":[]},{"id":"poem-e0425265f48639bd3246f701","title":"白雪歌送武判官归京","author":"岑参","dynasty":"唐","verses":["北风卷地白草折，胡天八月即飞雪。","忽然一夜春风来，千树万树梨花开。","散入珠帘湿罗幕，狐裘不煖锦衾薄。","将军角弓不得控，都护铁衣冷难着。","瀚海阑干百丈冰，愁云黪淡万里凝。","中军置酒饮归客，胡琴琵琶与羌笛。","纷纷暮雪下辕门，风掣红旗冻不翻。","轮台东门送君去，去时雪满天山路。","山回路转不见君，雪上空留马行处。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-294bc7b2-b4f8-4a53-be17-a40ded4afd1a","tags":["唐诗三百首","写雪","友情","咏物","八年级下册(课内)","送别","雪","初中古诗","冬天","山","七言古诗","咏物诗"]},{"id":"poem-e045e2e94946bacd5565bcab","title":"巴中逢故人","author":"项斯","dynasty":"唐","verses":["劳思空积岁，偶会更无由。","以分难相舍，将行且暂留。","路歧何处极，江峡半猨愁。","到此分南北，离怀岂易收。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-299e6f45-a91e-4790-ad6c-5472640d6f40","tags":[]},{"id":"poem-e04ba5b73c441bfcec300255","title":"哭押牙四寂","author":"佚名","dynasty":"唐","verses":["哀哉存殁苦难量，共恨沦流处异乡。","可叹生涯光景促，旋嗟死路夜何长！空令肝胆摧林竹，每使心魂痛渭阳。","缧绁时深肠自断，更闻凶变泪沾裳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d304f6a1-9dda-45e6-bf26-53b802315f77","tags":[]},{"id":"poem-e05491ce3a48f9159938d746","title":"双溪","author":"陈岩","dynasty":"宋","verses":["二水来从翠岭头，相逢涧谷却同流。","冷光如镜清人骨，探借山间六月秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5f3b3102-2df7-4b19-b112-e7c816e3cbe1","tags":[]},{"id":"poem-e05ebb053f62fe114d247473","title":"永明山居诗（六十九首） 六十","author":"延寿","dynasty":"唐","verses":["独行独坐任天然，幽隐难逢世网牵。","一志直教齐大道，万般总是涉因缘。","水磨涧石平如镜，春引岩藤直似弦。","虚幻已知休更续，蹄轮应不到山前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f7f6dbe3-1142-408b-b1b2-be122007194e","tags":[]},{"id":"poem-e061608fabe9813e582fa9fb","title":"溪居","author":"柳宗元","dynasty":"唐","verses":["久为簪组累，幸此南夷谪。","闲依农圃邻，偶似山林客。","晓耕翻露草，夜榜响溪石。","来往不逢人，长歌楚天碧。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-469dec8b-ba5e-4faf-b52f-2ad203e38d81","tags":["唐诗三百首","孤独","五言古诗","生活"]},{"id":"poem-e061944f95bd57c38c335cb5","title":"女冠子·锦江烟水","author":"牛峤","dynasty":"五代","verses":["锦江烟水，卓女烧春浓美。小檀霞。","绣带芙蓉帐，金钗芍药花。","额黄侵腻发，臂钏透红纱。","柳暗莺啼处，认郎家。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-1","tags":[]},{"id":"poem-e06b9d651dc264d9dda1c88f","title":"狼草生","author":"施惠《幽闺记》","dynasty":"元","verses":["(合)劲风寒四合，暮烟昏惨惨。","彤云布，晚天变，只愁那长空雪舞絮绵绵。","去心如箭，旅舍全无，何处安歇停眠？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3020","tags":[]},{"id":"poem-e06d930dfb5368db79f4fcf0","title":"苦雨奉寄陇西公兼呈王征士","author":"杜甫","dynasty":"唐","verses":["今秋乃淫雨，仲月来寒风。","群木水光下，万象云气中。","所思碍行潦，九里信不通。","悄悄素浐路，迢迢天汉东。","愿腾六尺马，背若孤征鸿。","划见公子面，超然欢笑同。","奋飞既胡越，局促伤樊笼。","一饭四五起，凭轩心力穷。","嘉蔬没混浊，时菊碎榛丛。","鹰隼亦屈猛，乌鸢何所蒙。","式瞻北邻居，取适南巷翁。","挂席钓川涨，焉知清兴终。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e018d77b-84a8-4e85-b9af-d81845efe2a6","tags":[]},{"id":"poem-e06e2398d12af7b79cf556e3","title":"赠王秘书","author":"张籍","dynasty":"唐","verses":["不曾浪出谒公侯，唯向花间水畔游。","每著新衣看药灶，多收古器在书楼。","有官祗作山人老，平地能开洞穴幽。","自领闲司了无事，得来君处喜相留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-05bf7ea8-b98c-4a8c-b488-557dc2ae0db6","tags":[]},{"id":"poem-e073e48618d24ddb98ebbbf0","title":"神功盛德诗  其一一","author":"华镇","dynasty":"宋","verses":["猗欤道真，厥心希微。","我则道之，万物纷错，我摄之以无为。","股肱良矣，心膂则奇。","荡荡妙用，民莫之知。","既绥寰中，亦静四夷。","承休垂裕，维君维师。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-3fb77dc5-1916-4e08-9fab-469a80412529","tags":[]},{"id":"poem-e0740c704a81382c4be773f8","title":"再游巾子山寺","author":"任翻","dynasty":"唐","verses":["灵江江上帻峰寺，三十年来两度登。","野鹤尚巢松树徧，竹房不见旧时僧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-f709816d-d21d-45db-963e-814ce89aba20","tags":[]},{"id":"poem-e0766b32c713ab0258c76677","title":"哭殷遥","author":"王维","dynasty":"唐","verses":["人生能几何，毕竟归无形。","念君等为死，万事伤人情。","慈母未及葬，一女才十龄。","泱漭寒郊外，萧条闻哭声。","浮云为苍茫，飞鸟不能鸣。","行人何寂寞，白日自凄清。","忆昔君在时，问我学无生。","劝君苦不早，令君无所成。","故人各有赠，又不及生平。","负尔非一途，恸哭返柴荆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-41355750-b4e1-4c5a-8fc6-17f4e8a7049e","tags":[]},{"id":"poem-e07c3a31b5ed1e7ab4845fa1","title":"蝶恋花·只恐深夜花睡去","author":"葛胜仲","dynasty":"宋","verses":["只恐深夜花睡去。","火照红妆，满意留宾住。","凤烛千枝花四顾。","消愁更待寻何处。","汉苑红光非浪语。","栖静亭前，都是珊瑚树。","便请催尊鸣釂鼓。","明朝风恶飘红雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-39","tags":[]},{"id":"poem-e07fe30f328621661073ef34","title":"谒金门·春尚浅","author":"韩元吉","dynasty":"宋","verses":["春尚浅。","谁把玉英裁翦。","尽道梅梢开未遍。","卷帘花满院。","楼上酒融歌暖。","楼下水平烟远。","却似涌金门外见。","絮飞波影乱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-791","tags":[]},{"id":"poem-e0843c5ab10915dce5aabb42","title":"句","author":"李伯良","dynasty":"唐","verses":["风向银灯花烬落，月临珠箔玉钩垂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7cd6d166-f4f3-4403-bcb6-466d83411a1e","tags":[]},{"id":"poem-e090108a11f0e4211c64e342","title":"松石  其二","author":"刘跂","dynasty":"宋","verses":["向来爱鼎已成癖，今日还书真是痴。","不分多求董威辇，只应重老李咸熙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-eb794f9f-be9d-455b-827a-2228f5e52550","tags":[]},{"id":"poem-e0903a884a1008c0bc53aebf","title":"思山居一十首 春日独坐思归","author":"李德裕","dynasty":"唐","verses":["壮龄心已尽，孤赏意犹存。","岂望图麟阁，惟思卧鹿门。","无谋堪适野，何力可拘原。","只有容身去，幽山自灌园。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-920a0be7-5088-4a6a-b724-bc765c5684fa","tags":[]},{"id":"poem-e098b4d8f914345b0f3baf7f","title":"吊元鲁山 六","author":"孟郊","dynasty":"唐","verses":["言从鲁山宦，尽化尧时心。","豺狼耻狂噬，齿牙闭霜金。","竞来辟田土，相与畊嵚岑。","当宵无关锁，竟岁饶歌吟。","善教复天术，美词非俗箴。","精微自然事，视听不可寻。","因书鲁山绩，庶合箫韶音。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-31ccc74f-fcdc-4ff9-a842-3380efbaaab2","tags":[]},{"id":"poem-e0997a21a2cb08fe146219dc","title":"江行无题一百首 三","author":"钱珝","dynasty":"唐","verses":["浦烟含夜色，冷日转秋旻。","自有沈碑在，清光不照人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-992a9fdb-a059-480a-af0b-d39f745ab7b6","tags":[]},{"id":"poem-e09bf1d8c1d2d20e2c61238a","title":"纸帐吟","author":"柴元彪","dynasty":"宋","verses":["有斐楮先生，复冒逈襟度。","澡身清泚泉，被世轶于布。","置之山斋中，朔风岁云暮。","无分媚其奢，可宝色惟素。","愧彼锦步障，荣华尘一聚。","永此雪霜洁，不识羔羊污。","影横月窗梅，香透地炉芋。","道人何太寂，新故谩纳吐。","勿为袁卧高，勿为庄梦栩。","愿均燠寒心，以散隆寒沍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-21373273-7548-4c6e-b8da-d058eec40a7c","tags":[]},{"id":"poem-e0a0d4bd4f62367772c33263","title":"天门谣·牛渚天门险","author":"贺铸","dynasty":"宋","verses":["牛渚天门险。","限南北、七雄豪占。","清雾敛。","与闲人登览。","待月上潮平波滟滟。","塞管轻吹新《阿滥》。","风满槛。","历历数、西州更点。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-103","tags":["宋词三百首"]},{"id":"poem-e0a2d3d6197820c68ad1742c","title":"西江月·雨后夹衣初冷","author":"毛滂","dynasty":"宋","verses":["雨后夹衣初冷，霜前细菊浑斑。","觚棱清月绣团环。","万里长安秋晚。","槽下内家玉滴，盘中江国金丸。","春容著面作微殷。","烛影红摇醉眼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-825","tags":[]},{"id":"poem-e0a6499eab8cb4fb3f1333ad","title":"题袁氏别业","author":"贺知章","dynasty":"唐","verses":["主人不相识，偶坐为林泉。","莫谩愁沽酒，囊中自有钱。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題袁氏別業","tags":[]},{"id":"poem-e0a96e79e2c6f444597ff5f3","title":"送杨长史赴果州","author":"王维","dynasty":"唐","verses":["襃斜不容幰，之子去何之。","鸟道一千里，猿声十二时。","官桥祭酒客，山木女郎祠。","别后同明月，君应听子规。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4787f534-eb1a-4c3b-a785-6e36eadf9f45","tags":["抒情","送别","写景"]},{"id":"poem-e0aaac3ebd8bd9c5ba8174db","title":"宫人斜","author":"雍裕之","dynasty":"唐","verses":["几多红粉委黄泥，野鸟如歌又似啼。","应有春魂化为燕，年来飞入未央栖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7d60413e-e371-4d78-81c7-64c671b37a6f","tags":[]},{"id":"poem-e0b51132bc6e3cf1a88b2057","title":"送句都官倅建阳","author":"苏颂","dynasty":"宋","verses":["玉岭名都古越疆，监州今用上台郎。","溪山绝胜神仙宅，弦诵相闻礼义乡。","龙焙枪旗争早晚，刺桐花叶候灾穰。","朝廷恤远频颁诏，更倚贤能慰一方。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7456b978-f256-4bcc-a0d4-5558fab147d8","tags":[]},{"id":"poem-e0b5cd0690b9cf0d64c6a36b","title":"偈颂十二首  其五","author":"释原妙","dynasty":"宋","verses":["五阴山中，魔强法弱。","战之不胜，休拟议著。","宝剑全提，莫问生杀。","奋不顾身，星飞火撒。","有功者赏，无功者罚。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-0b5d058a-f455-4bd3-9ea7-2d8e3176f2d4","tags":[]},{"id":"poem-e0b7b156afc11a6c3f0aca92","title":"怀古呈通守郑定斋  其一","author":"王柏","dynasty":"宋","verses":["东方有猗桐，菀彼云之岑。","良工一斤斧，斲为膝上琴。","朱弦轻拂抹，盎然太古音。","不弹箕子操，不调离骚声。","安得夔典乐，天下终和平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d7183193-5ad7-4bc5-83ef-1125465688fe","tags":[]},{"id":"poem-e0c1ff04ccb5eefda6589e36","title":"南乡子·路入南中","author":"欧阳炯","dynasty":"五代","verses":["路入南中，桃榔叶暗蓼花红。","两岸人家微雨后，收红豆，树底纤纤抬素手。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-5","tags":[]},{"id":"poem-e0ca0998c3bfeffb2101bb4c","title":"应天长·一钩初月临妆镜","author":"李璟","dynasty":"五代","verses":["一钩初月临妆镜，蝉鬓凤钗慵不整。","重帘静，层楼迥，惆怅落花风不定。","柳堤芳草径，梦断辘轳金井。","昨夜更阑酒醒，春愁过却病。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-0","tags":[]},{"id":"poem-e0cee43cc4cbc9767d3981fb","title":"樟亭观涛","author":"宋昱","dynasty":"唐","verses":["涛来势转雄，猎猎驾长风。","雷震云霓里，山飞霜雪中。","激流起平地，吹涝上侵空。","翕辟乾坤异，盈虚日月同。","艅艎从陆起，洲浦隔阡通。","跳沫喷岩翠，翻波带景红。","怒湍初抵北，却浪复归东。","寂听堪增勇，晴看自发蒙。","伍生传或谬，枚叟说难穷。","来信应无已，申威亦匪躬。","冲腾如决胜，回合似相攻。","委质任平视，谁能涯始终。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-bba2337f-5b4d-4097-ab92-f1f326570a15","tags":[]},{"id":"poem-e0d21a878e383f169fd2bd35","title":"萍乡春晚寓居（四首） 三","author":"沈彬","dynasty":"唐","verses":["黄鸟垂杨一两声，流年流去不胜情。","已伤野径锁春色，空睡山窻愁月明。","金山真堪沽酒散，山河到了为谁争。","古人尽入平芜去，虚对冯唐夸后生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6beb704e-487a-4055-9e33-7b73369c5b00","tags":[]},{"id":"poem-e0de2f76d26756cb4a8e00f9","title":"次韵张丞","author":"陈造","dynasty":"宋","verses":["政平民安之，不在书上考。","君看道傍樗，苍云荫合抱。","明时话英躔，佳气指蓬岛。","孰知嵌岩幽，乃韫希代宝。","张侯儒而吏，笞箠环台皂。","政声载舆论，文价动诸老。","学富食犹贫，志坚进不早。","即今紫霄人，岂必皆横草。","亦知名炜烨，曾上荐士表。","静女家无媒，深闺自媚好。","胡宁倚昌丰，浓抹且淡扫。","会看邢娥前，妬妇付绝倒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4d91e3b4-150f-4806-841d-5b7f30fbc74d","tags":[]},{"id":"poem-e0e9a1c76e7a4c91e13c64de","title":"鉴玄影堂","author":"李绅","dynasty":"唐","verses":["香灯寂莫网尘中，烦恼身须色界空。","龙钵已倾无法雨，虎床犹在有悲风。","定心池上浮泡没，招手岩边梦幻通。","深夜月明松子落，俨然听法侍生公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fe5d682f-3b84-420e-8efc-822711c9188d","tags":[]},{"id":"poem-e0f4dc52b0882f47e8e14b6d","title":"寄赠","author":"刘跂","dynasty":"宋","verses":["绝世丹青业，中台雨露辰。","师门推上第，王室见名臣。","磊落儒林丈，风流画省宾。","燕朝分锦仗，儤值近枫宸。","鸣凤丹山穴，占星颍水滨。","殿庐俄厌直，藩社此班春。","山节还铜虎，京符换玉麟。","威行三辅地，歌浃两川民。","已喜征黄霸，无劳借寇恂。","即应公简上，会见俗还淳。","叹昔时难偶，逢今势莫均。","楚材难入晋，汉法近沿秦。","稽古皆前列，希风绝后尘。","斯文如汩没，吾道久湮沦。","海岳功归圣，熊罴钓有人。","蓝田仍产玉，郢匠早挥斤。","周历方开永，萧规欲尽循。","天时知会遇，人力漫纷纶。","夙有掺弦便，今逢敛板亲。","猥惭牛下走，敢玷席中珍。","迹远龙门峻，心怀燕厦仁。","绪言闻已旧，从此更书绅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d794bfe5-9643-4792-ba6c-4e33fc112b38","tags":[]},{"id":"poem-e0f65649ce6d236359723f97","title":"相和歌辞 长信怨 二","author":"王昌龄","dynasty":"唐","verses":["奉帚平明金殿开，暂将团扇共裴回。","玉颜不及寒鵶色，犹带昭阳日影来。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1b6f2389-2d09-4d51-982a-e7efb35113c5","tags":["唐诗三百首"]},{"id":"poem-e0fa40c3a7fc28be67730bf2","title":"送柳震入蜀","author":"司空曙","dynasty":"唐","verses":["粉堞连青气，喧喧杂万家。","夷人祠竹节，蜀鸟乳桐花。","酒报新丰景，琴迎抵峡斜。","多闻滞游客，不似在天涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d3dc254c-55e1-4114-93e6-44ebc2f07232","tags":[]},{"id":"poem-e0fe45a7b86b759fa3738e54","title":"九华观看花","author":"张籍","dynasty":"唐","verses":["街西无数闲游处，不似九华仙观中。","花里可怜池上景，几重墙壁贮春风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8ccf17af-4e7a-46c0-826b-657b84f20989","tags":[]},{"id":"poem-e10286a2cd8f3a47236815dc","title":"和元晦赠上封长老","author":"张栻","dynasty":"宋","verses":["上方元自好，一榻有余清。","祇趁晨钟起，宁闻山鸟声。","高僧足幽事，野客富诗情。","试问峰头景，今朝作么生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-cabf4b9f-8a3b-4400-80ac-f8ea46f1c8e5","tags":[]},{"id":"poem-e10d60c1d2f7e477b9911c4a","title":"寄太白隐者","author":"李洞","dynasty":"唐","verses":["开辟已来雪，为山长欠春。","高遮辞碛雁，寒噤入川人。","栈阁交冰柱，耕樵隔日轮。","此中栖息者，不识两京尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-4c180b32-7be1-49fa-b26e-fc184487b4e5","tags":[]},{"id":"poem-e10e1bfe6f9387617cdaf1a4","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["不孝的媳妇，恨当初担阁我夫。","吃人笑谈生何补？我待死呵，又羞见公姑。","公公，婆婆，我生前未能相奉事，何如事你向黄泉路？只一件，我死呵，家中老父，教谁看顾？(合前)(旦唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5262","tags":[]},{"id":"poem-e110193bf211ba208520450d","title":"塘上行","author":"曹操","dynasty":"汉","verses":["蒲生我池中，其叶何离离。","傍能行仁义，莫若妾自知。","众口铄黄金，使君生别离。","念君去我时，独愁常苦悲。","想见君颜色，感结伤心脾。","念君常苦悲，夜夜不能寐。","莫以豪贤故，弃捐素所爱？","莫以鱼肉贱，弃捐葱与薤？","莫以麻枲贱，弃捐菅与蒯？","出亦复何苦，入亦复何愁。","边地多悲风，树木何修修！","从君致独乐，延年寿千秋。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-13","tags":[]},{"id":"poem-e11491626032ade853703667","title":"读杜工部集二首 一","author":"贯休","dynasty":"唐","verses":["造化拾无遗，唯应杜甫诗。","岂非玄域橐，夺得古人旗。","日月精华薄，山川气概卑。","古今吟不尽，惆怅不同时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-908f68ec-e7d3-4d08-9564-19f4b10d12ba","tags":[]},{"id":"poem-e118d14b87b4df8253fff292","title":"安国寺随驾幸兴唐观应制","author":"广宣","dynasty":"唐","verses":["东林何殿是西邻，禅客垣墙接羽人。","万乘游仙宗有道，三车引路本无尘。","初传宝诀长生术，已证金刚不坏身。","两地尽修天上事，共瞻銮驾重来巡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-76be28ad-f2ca-4efc-b6f1-a0a8660ce410","tags":[]},{"id":"poem-e1272917a443467156f40478","title":"人娇·一叶秋高","author":"晏殊","dynasty":"宋","verses":["一叶秋高，向夕红兰露坠。","风月好、乍凉天气。","长生此日，见人中嘉瑞。","斟寿酒、重唱妙声珠缀。","凤莞移宫，钿衫回袂。","帘影动、鹊炉香细。","南真宝箓，赐玉京千岁。","良会永、莫惜流霞同醉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-503","tags":[]},{"id":"poem-e12883c00ac08a678cee536c","title":"赠卫八处士","author":"杜甫","dynasty":"唐","verses":["人生不相见，动如参与商。","今夕复何夕，共此灯烛光。","少壮能几时，鬓发各已苍。","访旧半为鬼，惊呼热中肠。","焉知二十载，重上君子堂。","昔别君未婚，儿女忽成行。","怡然敬父执，问我来何方。","问荅乃未已，儿女罗酒浆。","夜雨剪春韭，新炊间黄粱。","主称会面难，一举累十觞。","十觞亦不醉，感子故意长。","明日隔山岳，世事两茫茫。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6c7c45a6-c944-4ff3-aa99-f5cb0440436f","tags":["唐诗三百首","时光","五言古诗","人生","友情"]},{"id":"poem-e12d1d2d1dbb4a76bc8d8bd5","title":"送陈元龙赴封州教官","author":"王十朋","dynasty":"宋","verses":["温陵尊酒偶相逢，记得同年旧日容。","书读短檠游太学，经传绛帐适临封。","清新得句肠生锦，瘦硬通神笔吐锋。","莫向炎州叹官冷，行看胡海起元龙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-cd5e8627-788f-4f64-a064-e64169327167","tags":[]},{"id":"poem-e1327f044dd42450593a6f7b","title":"观野烧","author":"吕从庆","dynasty":"唐","verses":["烈烈西风里，蓬芜一扫空。","虽留生意在，已废半年功。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0df441d8-38c9-407d-9c0a-51361fca1f87","tags":[]},{"id":"poem-e135c42aaffafab8508a4976","title":"赵皮鞋","author":"无名氏《张协状元》","dynasty":"元","verses":["我的状元分付它：官员相见便没奈何。","还是妇女庄家到厅下，十三小杖，把门子打。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2655","tags":[]},{"id":"poem-e13b8a3697614804da50f06e","title":"重画知识壁","author":"释了惠","dynasty":"宋","verses":["幸自十方无壁落，谁将五彩画虚空。","善财眼里生花翳，去却一重添一重。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-11ab9f5d-2c4c-4bda-be2f-3e973666db19","tags":[]},{"id":"poem-e13dd3535e3179709c1ec906","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十三","author":"易静","dynasty":"唐","verses":["生门下，辛仪艮位安。","此处一方为虎遁，招安反贼讨交关，将帅总平安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b56f179e-c94d-4743-960d-ea614aae1707","tags":[]},{"id":"poem-e13deafd99678a3e4e8b1986","title":"再用才子富文华校雠天禄阁韵赠周教授  其九","author":"陈造","dynasty":"宋","verses":["万木同一秋，松柏正也独。","夫君阅流俗，尘过不留目。","我昔甘曳裾，低首问宜禄。","及今君子前，玩易愧频复。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-68176a73-d740-4398-9244-dd81231837a3","tags":[]},{"id":"poem-e13fe1c19fd43656d56c951d","title":"寄别者","author":"张籍","dynasty":"唐","verses":["寒天正飞雪，行人心切切。","同为万里客，中路忽离别。","别君汾水东，望君汾水西。","积雪无平冈，空山无人蹊。","羸马时倚辕，行行未遑食。","下车劝僮仆，相顾莫叹息。","讵知佳期隔，离念终无极。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a3b26734-32e3-4c56-a6d2-fa8a2a206fc0","tags":[]},{"id":"poem-e142688b0e0d244000358963","title":"宫词  其八五","author":"张公庠","dynasty":"宋","verses":["掖庭初选即知名，新学吹箫数曲成。","天上仙姝元不识，人间安得咏倾城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7faf35f7-8692-426b-802f-dd2d6955302a","tags":[]},{"id":"poem-e15752c54075533ecb88ba5e","title":"喜迁莺·谯门残月","author":"史浩","dynasty":"宋","verses":["谯门残月。","正画角晓寒，梅花吹彻。","瑞日烘云，和风解冻，青帝乍临东阙。","暖响土牛箫鼓，夹路珠帘高揭。","最好是，看彩幡金胜，钗头双结。","奇绝。","开宴处，珠履玳簪，俎豆争罗列。","舞袖翩翻，歌声缥缈，压倒柳腰莺舌。","劝我应时纳祜，还把金炉香𦶟。","愿岁岁，这一卮春酒，长陪佳节。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-69","tags":[]},{"id":"poem-e15ced2fbde693e6643bcf1f","title":"椀柏","author":"释居简","dynasty":"宋","verses":["土入花甆浅，林疏雪操鲜。","后凋非地力，独秀是天年。","老我不谐俗，惜才如养贤。","明明千古意，渠自指庭前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-af89db8e-1875-4aca-95a7-2dfbae0a3503","tags":[]},{"id":"poem-e15d25af865c0e52a6b12014","title":"送于兢补阙赴京","author":"贯休","dynasty":"唐","verses":["乱离吾道在，不觉到清时。","得句下雪岳，送君登玉墀。","冷惊蝉韵断，凉触火云隳。","倘遇南来使，无忘问所之。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c9a02462-e7d8-40d1-a13a-b1c674e72353","tags":[]},{"id":"poem-e15d7a101f572b7dc9ddaa80","title":"秋日奉陪王丰甫许子大康平仲游贤沙宿凤池登升山偶成二首  其二","author":"李纲","dynasty":"宋","verses":["追陪杖屦极幽寻，共宿精庐上翠岑。","凤鸟不来空碧沼，仙人已去得黄金。","月林散影琼瑶碎，烟水澄光组练深。","欲把诗篇与收拾，登临谁会此时心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5f536219-ea0d-4a76-9f3d-2ad8f2ae905a","tags":[]},{"id":"poem-e15dc5e2461e6e8fb0cfeb9e","title":"送顾处士歌","author":"皎然","dynasty":"唐","verses":["吴门顾子予早闻，风貌真古谁似君。","人中黄宪与颜子，物表孤高将片云。","性背时人高且逸，平生好古无俦匹。","醉书在箧称绝伦，神画开厨怕飞出。","谢氏檀郎亦可俦，道情还似我家流。","安贫日日读书坐，不见将名干五侯。","知君别业长洲外，欲行秋田循畎浍。","门前便取觳觫乘，腰上还将鹿卢佩。","禅子有情非世情，御荈贡余聊赠行。","满道喧喧遇君别，争窥玉润与冰清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-db20c6f2-4d08-4acf-a055-5fe1a4ff4af8","tags":[]},{"id":"poem-e1683bf7325248cea0036bd6","title":"渔父歌","author":"高适","dynasty":"唐","verses":["曲岸深潭一山叟，驻眼看钩不移手。","世人欲得知姓名，良久问他不开口。","笋皮笠子荷叶衣，心无所营守钓矶。","料得孤舟无定止，日暮持竿何处归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0be9008f-d175-47f6-aa53-87fce8d020fa","tags":[]},{"id":"poem-e16e32975978be69f203a958","title":"雪","author":"李咸用","dynasty":"唐","verses":["上帝无私意甚微，欲教霖雨更光辉。","也知出处花相似，可到贫家影便稀。","云汉风多银浪溅，昆山火后玉灰飞。","高楼四望吟魂敛，却忆明皇月殿归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9b71846e-8e13-439b-b1aa-7580b8b9f9fa","tags":[]},{"id":"poem-e16e5dce331b9372d034dcbf","title":"恋情深·滴滴铜壶塞漏咽","author":"毛文锡","dynasty":"五代","verses":["滴滴铜壶塞漏咽，醉红楼月。","宴余香殿会鸳衾，荡春心。","真珠帘下晓光侵，莺语隔琼林。","宝帐欲开慵起，恋情深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-26","tags":[]},{"id":"poem-e17f2d0c3009632be4398d4a","title":"寄驾部郎中","author":"徐铉","dynasty":"宋","verses":["贱子乖慵性，频为省直牵。","交情每相见，多在相门前。","君独疏名路，为郎过十年。","炎风久成别，南望思悠然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-1778c75b-cfde-497b-ba52-b58368116d42","tags":[]},{"id":"poem-e18733a990aab03f576c7de1","title":"塞下曲四首 二","author":"王昌龄","dynasty":"唐","verses":["饮马渡秋水，水寒风似刀。","平沙日未没，黯黯见临洮。","昔日长城战，咸言意气高。","黄尘足今古，白骨乱蓬蒿。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-59fb3f01-65b2-416a-aefb-c13e502bfba1","tags":["唐诗三百首","战争","新乐府辞","乐府"]},{"id":"poem-e18ba5211dfc97fa680e961d","title":"浣溪沙·云薄罗裙绶带长","author":"毛熙震","dynasty":"五代","verses":["云薄罗裙绶带长，满身新裛瑞龙香，翠钿斜映艳梅妆。","佯不觑人空婉约，笑和娇语太猖狂，忍教牵恨暗形相。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-37","tags":[]},{"id":"poem-e193eb873702c664d85f77eb","title":"繙书见舍弟去年自寿归郓道中诗怅然怀想久不作诗因集句为答用渭城体可歌也  其一","author":"刘跂","dynasty":"宋","verses":["春深逐客一浮萍，何处淹留白发生。","山城过雨百花尽，野渡无人舟自横。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-ef790a85-7515-4226-8059-8d12f6227eda","tags":[]},{"id":"poem-e1a6d6a1bd5355cc9ecdefa2","title":"葛仙井","author":"任翻","dynasty":"唐","verses":["古井碧沈沈，分明见百寻。","味甘传邑内，脉冷应山心。","圆入月轮净，直涵峰影深。","自从仙去后，汲引到如今。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-300aa35a-b18a-4b04-8c8b-9f625cb15c7b","tags":[]},{"id":"poem-e1a7891ea17b05737db13f52","title":"𬳶","author":"佚名","dynasty":"先秦","verses":["𬳶𬳶牡马，在坰之野。薄言𬳶者，有驈有皇，有骊有黄，以车彭彭。思无疆思，马斯臧。","𬳶𬳶牡马，在坰之野。薄言𬳶者，有骓有𬳵，有骍有骐，以车伾伾。思无期思，马斯才。","𬳶𬳶牡马，在坰之野。溥言𬳶者，有驒有骆，有骝有雒，以车绎绎。思无斁思，马斯作。","𬳶𬳶牡马，在坰之野。薄言𬳶者，有骃有騢，有驔有鱼，以车祛祛。思无邪思，马斯徂。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-296","tags":[]},{"id":"poem-e1be0c5c68e13980712ec1e9","title":"戈","author":"李峤","dynasty":"唐","verses":["富父舂喉日，殷辛漂杵年。","晓霜含白刃，落影驻雕鋋。","夕摈金门侧，朝提玉塞前。","愿随龙影度，横阵彗云边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9f502d35-815f-4bb8-acf1-bae384137560","tags":[]},{"id":"poem-e1c9fe49bfa7412f12e70f7b","title":"投赠张鸿（题拟）","author":"孟宾于","dynasty":"唐","verses":["自怜成事攀仙桂，谁似投闲向草莱。","（见康熙《连州志》卷五《张鸿传》引。","又收入《粤诗搜逸》卷一。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2e8be905-f108-4588-baca-0251bdeb01c3","tags":[]},{"id":"poem-e1d41e32284a6862434f4ad4","title":"辟阳城","author":"高适","dynasty":"唐","verses":["荒城在高岸，凌眺俯清淇。","传道汉天子，而封审食其。","奸淫且不戮，茅土孰云宜。","何得英雄主，返令儿女欺。","母仪良已失，臣节岂如斯。","太息一朝事，乃令人所嗤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7d8d9dcc-9ef1-4fa9-9138-39a17fce08b4","tags":[]},{"id":"poem-e1dbed375d745aba89c392e6","title":"偕同人登虞山乾元宫","author":"孙介","dynasty":"宋","verses":["尘嚣咫尺愧山林，胜日追凉得共临。","千里江湖堪送目，一轩松竹更论心。","清风便自生秋意，小酌何妨到夕阴。","归路蝉声满溪谷，为君倚盖一微吟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-42dc27d7-1ce5-4072-999c-cf00700a3d23","tags":[]},{"id":"poem-e1e1b5d2bf083270129a2fde","title":"虞美人·触帘风送景阳钟","author":"顾敻","dynasty":"五代","verses":["触帘风送景阳钟，鸳被绣花重。","晓帷初卷冷烟浓，翠匀粉黛好仪容，思娇慵。","起来无语理朝妆，宝匣镜凝光。","绿荷相倚满池塘，露清枕簟藕花香，恨悠扬。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-34","tags":[]},{"id":"poem-e1edd41196ed570fceff168c","title":"了语","author":"雍裕之","dynasty":"唐","verses":["扫却烟尘寇初勦，深水高林放鱼鸟。","鸡人唱绝残漏晓，仙乐拍终天悄悄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-71c886d4-010e-48eb-ade3-d6bef06a89a3","tags":[]},{"id":"poem-e1f16ddaab04233c9cff4092","title":"小游仙诗九十八首 五十三","author":"曹唐","dynasty":"唐","verses":["赤龙停步彩云飞，共道真王海上归。","千岁红桃香破鼻，玉盘盛出与金妃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6176e93a-b752-4649-a999-d98e87b26d5d","tags":[]},{"id":"poem-e1fb071fe7691c66c4f7a5eb","title":"鹧鸪天·领客携尊花底开","author":"洪适","dynasty":"宋","verses":["领客携尊花底开。","薄寒初送雨声来。","一声未弄林间笛，几片低飞阁下梅。","酬的皪，少迟回。","不妨春雪撒银杯。","玉肌莫放清香散，更待晴时赏一回。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-683","tags":[]},{"id":"poem-e1fb25175f591254ca460885","title":"九思·伤时","author":"王逸","dynasty":"汉","verses":["惟昊天兮昭灵，阳气发兮清明。","风习习兮和暖，百草萌兮华荣。","堇荼茂兮扶疏，蘅芷雕兮莹嫇。","愍贞良兮遇害，将夭折兮碎糜。","时混混兮浇饡，哀当世兮莫知。","览往昔兮俊彦，亦诎辱兮系累。","管束缚兮桎梏，百贸易兮传卖。","遭桓缪兮识举，才德用兮列施。","且从容兮自慰，玩琴书兮游戏。","迫中国兮迮陿，吾欲之兮九夷。","超五岭兮嵯峨，观浮石兮崔嵬。","陟丹山兮炎野，屯余车兮黄支。","就祝融兮稽疑，嘉己行兮无为。","乃回朅兮北逝，遇神孈兮宴娭。","欲静居兮自娱，心愁戚兮不能。","放余辔兮策驷，忽飙腾兮浮云。","跖飞杭兮越海，从安期兮蓬莱。","缘天梯兮北上，登太一兮玉台。","使素女兮鼓簧，乘戈和兮讴谣。","声噭誂兮清和，音晏衍兮要婬。","咸欣欣兮酣乐，余眷眷兮独悲。","顾章华兮太息，志恋恋兮依依。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-62","tags":[]},{"id":"poem-e1fb81311d22124d360f0a6f","title":"感石浮图","author":"王英","dynasty":"唐","verses":["树福金岩顶，粧岩琢石成。","真容绘美素，图镂万年荣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d7cdcdef-7ad2-41c3-9ff3-be8e1b6bd497","tags":[]},{"id":"poem-e2141f8b92827f0cd45be1d2","title":"岳州晚景","author":"张籍","dynasty":"唐","verses":["晚景寒鸦集，秋声旅雁归。","水光浮日去，霞彩暎江飞。","洲白芦花吐，园红柿叶稀。","长沙卑湿地，九月未成衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8e8b950d-862a-4c8d-9fe5-8327e4d31eb9","tags":[]},{"id":"poem-e2160a83f88e4fce0208751d","title":"节南山","author":"佚名","dynasty":"先秦","verses":["节彼南山，维石岩岩。赫赫师尹，民具尔瞻。忧心如惔，不敢戏谈。国既卒斩，何用不监！","节彼南山，有实其猗。赫赫师尹，不平谓何。天方荐瘥，丧乱弘多。民言无嘉，惨莫惩嗟。","尹氏大师，维周之氐；秉国之钧，四方是维。天子是毗，俾民不迷。不吊昊天，不宜空我师。","弗躬弗亲，庶民弗信。弗问弗仕，勿罔君子。式夷式已，无小人殆。琐琐姻亚，则无膴仕。","昊天不佣，降此鞠讻。昊天不惠，降此大戾。君子如届，俾民心阕。君子如夷，恶怒是违。","不吊昊天，乱靡有定。式月斯生，俾民不宁。忧心如酲，谁秉国成？不自为政，卒劳百姓。","驾彼四牡，四牡项领。我瞻四方，蹙蹙靡所骋。","方茂尔恶，相尔矛矣。既夷既怿，如相酬矣。","昊天不平，我王不宁。不惩其心，覆怨其正。","家父作诵，以究王讻。式讹尔心，以畜万邦。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-190","tags":[]},{"id":"poem-e2177e4566bde4434b98752d","title":"柳絮","author":"杨凝","dynasty":"唐","verses":["河畔多杨柳，追游尽狭斜。","春风一回送，乱入莫愁家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a5b107aa-c8fe-43b3-a3af-631a839b9a40","tags":[]},{"id":"poem-e21cd4f19e9e3ac131da31b7","title":"游长宁公主流杯池二十五首 十六","author":"上官昭容","dynasty":"唐","verses":["泉石多仙趣，岩壑写奇形。","欲知堪悦耳，唯听水泠泠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f44c2a8c-9a5a-4056-a0f0-a6b06e943b1e","tags":[]},{"id":"poem-e22055a29c3e13caa8590086","title":"虞美人·军书未息梅仍破","author":"苏庠","dynasty":"宋","verses":["军书未息梅仍破。","穿市溪流过。","病来无处不关情。","一夜鸣榔急雨、杂滩声。","飘零无复还山梦。","云屋春寒重。","山连积水水连空。","溪上青蒲短短、柳重重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-677","tags":[]},{"id":"poem-e222f2e4695d7f21886b1ce6","title":"建炎丞相成国吕忠穆公退老堂  其二","author":"胡舜陟","dynasty":"宋","verses":["为闻仙伯隐丹丘，三径新开结胜游。","庭户招呼松桂月，樽罍追逐芰荷秋。","晓猿夜鹤空留恋，风虎云龙自应求。","已拥帅旄将入觐，运筹破虏此归休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8d2f0917-42c6-49c9-8288-1addd781425a","tags":[]},{"id":"poem-e2328cf60a0d03c9a16d493d","title":"无题二首 二","author":"李商隐","dynasty":"唐","verses":["重帷深下莫愁堂，卧后清宵细细长。","神女生涯原是梦，小姑居处本无郎。","风波不信菱枝弱，月露谁教桂叶香。","直道相思了无益，未妨惆怅是清狂。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-b6475dea-1d69-4f0d-b98a-39393f47741e","tags":["唐诗三百首","思念","七言律诗","抒情","爱情"]},{"id":"poem-e237f393e3fabcd9f9bdb1d5","title":"祝英台令·宝钗分","author":"辛弃疾","dynasty":"宋","verses":["宝钗分，桃叶渡。","烟柳暗南浦。","怕上层楼，十日九风雨。","断肠片片飞红，都无人管，倩谁唤、流莺声住。","鬓边觑。","试把花卜心期，才簪又重数。","罗帐灯昏，呜咽梦中语。","是他春带愁来，春归何处。","却不解、将愁归去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-213","tags":["宋词三百首"]},{"id":"poem-e239ca9f7ef43a2be98667c9","title":"高阳台·修竹凝妆","author":"吴文英","dynasty":"宋","verses":["修竹凝妆，垂杨驻马，凭阑浅画成图。","山色谁题，楼前有雁斜书。","东风紧送斜阳下，弄旧寒、晚酒醒馀。","自销凝，能几花前，顿老相如。","伤春不在高楼上，在灯前攲枕，雨外熏炉。","怕舣游船，临流可奈清臞。","飞红若到西湖底，搅翠澜、总是愁鱼。","莫重来，吹尽香绵，泪满平芜。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-78","tags":["宋词三百首","西湖"]},{"id":"poem-e2429d946abc9207eaf7d016","title":"丰年多庆九日示怀","author":"德宗皇帝","dynasty":"唐","verses":["爽气肃时令，早衣闻朔鸿。","重阳有佳节，具物欣年丰。","皎洁暮潭色，芬敷新菊丛。","芳尊满衢室，繁吹凝烟空。","惠合信吾道，保和惟尔同。","推诚至玄化，天下期为公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-776916a8-bf58-4662-9596-e233239efdec","tags":[]},{"id":"poem-e24534080c7fbae8837c26f2","title":"幽居作","author":"李端","dynasty":"唐","verses":["山舍千年树，江亭万里云。","回潮迎伍相，骤雨送湘君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a0737190-4461-4ec7-b548-8b1534b87e47","tags":[]},{"id":"poem-e25da707a17f25d35d7547a4","title":"乐城白鹤寺","author":"沈佺期","dynasty":"唐","verses":["碧海开龙藏，青云起雁堂。","潮声迎法鼓，雨气湿天香。","树接前山暗，溪承瀑水凉。","无言谪居远，清净得空王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e4c988e1-7771-45dc-8c48-80fe1451233c","tags":[]},{"id":"poem-e26094c03e895db6122aeea8","title":"点绛唇·不昧本来","author":"向子𬤇","dynasty":"宋","verses":["不昧本来，太虚明月流辉过。","令行独坐。","高下都由我。","玉轸无弦，谁对秋风和。","还知么。","老庞一个。","识得机关破。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-150","tags":[]},{"id":"poem-e264ad06e04d3d0f7e3b05be","title":"学馆闲题","author":"宋伯仁","dynasty":"宋","verses":["据见定时俱是足，苦思量处便成痴。","请君打退闲烦恼，啜粥烹茶细和诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1ac69fe0-d387-4d00-8f27-d0ec686cee00","tags":[]},{"id":"poem-e26b66eff72866ef6132fc45","title":"城东早春","author":"杨巨源","dynasty":"唐","verses":["诗家清景在新春，绿柳才黄半未匀。","若待上林花似锦，出门俱是看花人。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-城東早春","tags":[]},{"id":"poem-e26de2c97e4c304914268acf","title":"南歌子·岸柳拖烟绿","author":"张泌","dynasty":"五代","verses":["岸柳拖烟绿，庭花照日红。","数声蜀魄入帘栊，惊断碧窗残梦，画屏空。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-48","tags":[]},{"id":"poem-e274d5bf119605f0647651f0","title":"行路难二首 二","author":"高适","dynasty":"唐","verses":["君不见富家翁，旧时贫贱谁比数。","一朝金多结豪贵，万事胜人健如虎。","子孙成行满眼前，妻能管弦妾能舞。","自矜一身忽如此，却笑傍人独愁苦。","东邻少年安所如，席门穷巷出无车。","有才不肯学干谒，何用年年空读书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7b8079ae-910c-4680-883a-6f747712ce0d","tags":[]},{"id":"poem-e277b8238d48db1cc32cbffe","title":"送零陵贾使君二首  其一","author":"张栻","dynasty":"宋","verses":["借甚零陵郡，风流记昔贤。","宅存元水部，人识范忠宣。","山近地宜竹，溪清岸有泉。","官闲时访古，余韵故依然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b5f44cf2-1521-4100-b174-a961536c8ab4","tags":[]},{"id":"poem-e2826afbde87e475d609c4bb","title":"游子吟","author":"李益","dynasty":"唐","verses":["女羞夫壻薄，客耻主人贱。","遭遇同众流，低回媿相见。","君非青铜镜，何事空照面。","莫以衣上尘，不谓心如练。","人生当荣盛，待士勿言倦。","君看白日驰，何异弦上箭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c50617c3-db50-4e02-a04f-c875072e9a89","tags":[]},{"id":"poem-e28aef3c6571f67466e67932","title":"再次韵","author":"陈造","dynasty":"宋","verses":["载羽其觞，客遄于行。","归从我私，兹焉用情。","一奇搴秀，万金论士。","生世已后，识古君子。","宫倡羽随，至乐则和。","俚音间之，人谓斯何。","洁不容缁，薰不莸改。","言受此柄，劣副期待。","斯道在公，九报其章。","人徯时施，跻之阜康。","曾是伟人，而未闻政。","袖司命手，旁睨世病。","海濒埤污，苍山周遭。","觞咏翺翔，乐殊尔曹。","盍摅胸奇，焕我王度。","盍提公言，辟我贤路。","赫日中天，丽彼南山。","赓歌交修，不腼其颜。","有铅者刀，用或一切。","云龙从之，无重此别。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-490a2b20-177a-49e2-8ab2-bd7af58aa7f3","tags":[]},{"id":"poem-e28c1e03542b70e078b5f676","title":"东方之日","author":"佚名","dynasty":"先秦","verses":["东方之日兮，彼姝者子，在我室兮。在我室兮，履我即兮。","东方之月兮，彼姝者子，在我闼兮。在我闼兮，履我发兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-98","tags":[]},{"id":"poem-e28cd5f9acae29f006bfa96d","title":"往返逾万里首尾涉五年幸无惊忧归次贵溪仙岩新罹寇盗焚荡孑然始见兵火之迹感怆有作二首  其一","author":"李纲","dynasty":"宋","verses":["梦里幽人独往来，僊岩依旧碧崔嵬。","伤心二百载涵养，极望皆成瓦砾堆。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e85da0ff-bf0d-4dae-bc2e-145fa2be94d0","tags":[]},{"id":"poem-e28d72500164fc277d822e44","title":"奉和圣制龙池篇","author":"卢怀慎","dynasty":"唐","verses":["代邸东南龙跃泉，清漪碧浪远浮天。","楼台影就波中出，日月光疑镜里悬。","雁沼洄流成舜海，龟书荐社应尧年。","大川既济慙为楫，报德空思奉细涓。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-525315c3-238f-40cd-9433-be42332174d3","tags":[]},{"id":"poem-e28ee5a51acbfa1161359734","title":"幸蜀回至剑门","author":"李隆基","dynasty":"唐","verses":["剑阁横云峻，銮舆出狩回。","翠屏千仞合，丹嶂五丁开。","灌木萦旗转，仙云拂马来。","乘时方在德，嗟尔勒铭才。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-幸蜀回至劍門","tags":[]},{"id":"poem-e29d60437fd2ca27dd37782d","title":"浮江探梅","author":"林宪","dynasty":"宋","verses":["清游可以愈宿疾，梅花自能来好人。","嗅花徐步沙碛里，天风液液回三春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c620921c-8403-4d86-a635-294079460168","tags":[]},{"id":"poem-e2ad4af3e72aa40e0effeeeb","title":"诗品二十四则 疎野","author":"司空图","dynasty":"唐","verses":["惟性所宅，真取弗羁。","拾物自富，与率为期。","筑屋松下，脱帽看诗。","但知旦暮，不辨何时。","倘然适意，岂必有为。","若其天放，如是得之。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6bf0d96c-74c2-4f65-b53d-c50571102a1d","tags":[]},{"id":"poem-e2b1b625592b18b99aeddae7","title":"句","author":"游士藻","dynasty":"唐","verses":["虚饤玲珑石镇羊。","（见《惜阴轩丛书》本《清异录》卷上。","）（按：五代封晋王者有数人，士藻所从，未详为谁。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-27349732-2fd3-4fd5-8414-5792e4824da4","tags":[]},{"id":"poem-e2c25458599ad0f4a215ef82","title":"临江仙","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["玉作人间秋万顷，银葩点破琉璃。","(贴)瑶台风露冷仙衣，天香飘下处，此景有谁知？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5150","tags":[]},{"id":"poem-e2c6fbb0d965f9e24c4c783f","title":"新城精舍","author":"陈岩","dynasty":"宋","verses":["朱甍碧瓦粉墙围，花舫回光洞户辉。","自是故家开第宅，乔林景物两芳菲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-36101ff8-7977-4124-8101-8208818b2a0b","tags":[]},{"id":"poem-e2c8b6eeeb94f050fae4e1a7","title":"送温初下第","author":"孟郊","dynasty":"唐","verses":["日落浊水中，夜光谁能分。","高怀无近趣，清抱多远闻。","欲识丈夫志，心藏孤岳云。","长安风尘别，咫尺不见君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d7be84a2-5ba3-47f7-8305-00b604fcc052","tags":[]},{"id":"poem-e2c8c7ffb5b87e87c0f0e36c","title":"寄窦禅山薛秀才","author":"李洞","dynasty":"唐","verses":["窦岭吟招隐，新诗满集贤。","白衫春絮暖，红纸夏云鲜。","琴缠江丝细，棋分海石圆。","因知醉公子，虚写世人传。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7a805bb5-b15f-4ea5-aa59-b2b16557c22d","tags":[]},{"id":"poem-e2cd4be87f5c5a59fe87da52","title":"偈颂七十一首  其三三","author":"释了惠","dynasty":"宋","verses":["大千总是神仙药，此药无多灵验多。","七佛之师虽解用，难医无病老维摩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cf63f1a1-8b2b-4d4a-a53f-46507fbb3178","tags":[]},{"id":"poem-e2d789ff572ec253c6dff596","title":"逸人歌赠李山人","author":"张楚金","dynasty":"唐","verses":["上有尧兮下有田，眠松阳兮漱颍流。","其貌古，其心幽，浩歌一曲兮林壑秋。","道险可惊兮人莫用，乐天知命兮守岩洞。","时击磬兮嗟鸣凤，吾欲知往古之不可追，自悠悠于凡梦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ab3e9d77-64ad-41b0-866f-3b51e0f9387b","tags":[]},{"id":"poem-e2e53accc3983ccfe4f33a4c","title":"湖上","author":"王镃","dynasty":"宋","verses":["万红飞尽雨如烟，心事伤春哭杜鹃。","游子不来弦管歇，画船空系柳丝边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-339b1c79-25a9-4014-a942-9a6329bb0577","tags":[]},{"id":"poem-e2e7c99949ac6f7f5dc1338f","title":"别杨秀才","author":"李山甫","dynasty":"唐","verses":["因乱与君别，相逢悲且惊。","开襟魂自慰，拭泪眼空明。","故国已无业，旧交多不生。","如何又分袂，难话别离情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-409a9707-4097-4323-8693-49ee24a47bd0","tags":[]},{"id":"poem-e2f22b6eb0ebab1e94a509fc","title":"邯郸驿楼作","author":"马戴","dynasty":"唐","verses":["芜没丛台久，清漳废御沟。","蝉鸣河外树，人在驿西楼。","云烧天中赤，山当日落秋。","近郊经战后，处处骨成丘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d9202065-0811-4720-87a3-d288cde39cbb","tags":[]},{"id":"poem-e2f9a7d8c6bd0a34c4596ee0","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(众)寻不见连忙向前，搜索尽墙边院边。","莫不是隐身法术似神仙？走如烟，眼寻穿。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2883","tags":[]},{"id":"poem-e302a7c7c88b5eac54372815","title":"薤露行","author":"曹操","dynasty":"汉","verses":["惟汉廿二世，所任诚不良。","沐猴而冠带，知小而谋疆。","犹豫不敢断，因狩执君王。","白虹为贯日，己亦先受殃。","贼臣持国柄，杀主灭宇京。","荡覆帝基业，宗庙以燔丧。","播越西迁移，号泣而且行。","瞻彼洛城郭，微子为哀伤。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-14","tags":[]},{"id":"poem-e3082ff1f6be6864081884ae","title":"南柯子・南歌子·宝合分时果","author":"周邦彦","dynasty":"宋","verses":["宝合分时果，金盘弄赐冰。","晓来阶下按新声。","恰有一方明月、可中庭。","露下天如水，风来夜气清。","娇羞不肯傍人行。","扬下扇儿拍手、引流萤。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-519","tags":[]},{"id":"poem-e30ac21e72d3bff0456eafb0","title":"寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 忆东湖","author":"李绅","dynasty":"唐","verses":["菱歌罢唱鹢舟回，雪鹭银鸥左右来。","霞散浦边云锦截，月升湖面镜波开。","鱼惊翠羽金鳞跃，莲脱红衣紫菂摧。","淮口值春偏怅望，数株临水是寒梅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-59730cd8-6333-485a-a0e8-79635c51ebb6","tags":[]},{"id":"poem-e30fba61f36823f90a7de1f6","title":"青玉案·良夜灯光簇如豆","author":"周邦彦","dynasty":"宋","verses":["良夜灯光簇如豆。","占好事、今宵有。","酒罢歌阑人散后。","琵琶轻放，语声低颤，灭烛来相就。","玉体偎人情何厚。","轻惜轻怜转唧𠺕。","雨散云收眉儿皱。","只愁彰露，那人知后。","把我来僝僽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-502","tags":[]},{"id":"poem-e31245dd603842b05eca824e","title":"女冠子·蕙风芝露","author":"孙光宪","dynasty":"五代","verses":["蕙风芝露，坛际残香轻度。","蕊珠宫，苔点分圆碧，桃花践破红。","品流巫峡外，名籍紫微中。","真侣墉城会，梦魂通。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-23","tags":[]},{"id":"poem-e3146b96d185fb1c873239c4","title":"自夏口至鹦鹉洲夕望岳阳寄源中丞","author":"刘长卿","dynasty":"唐","verses":["[汀]洲无浪复无烟，楚客相思益渺然。","汉口夕阳斜渡鸟，洞庭秋水远连天。","孤城背岭寒吹角，独戍临江夜泊船。","贾谊上书忧汉室，长沙谪去古今怜。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-3f049d66-1513-407f-bb4e-cf25a7b5069a","tags":["唐诗三百首","洞庭湖","贬谪","七言律诗","触景感怀"]},{"id":"poem-e3194ca912c0605975092961","title":"·（按《全唐诗》无吕从庆诗","author":"吕从庆","dynasty":"唐","verses":["（按《全唐诗》无吕从庆诗。","今传世之《丰溪存稿》，即吕从庆诗集也。","此书有洪溪吕氏萃石山房本，有嘉庆癸酉岁从庆三十二世孙吕玺培重刊本，均未见。","有同治癸酉六安西乡流波䃥镇弗措书屋重镌本。","此卷即自同治重镌本录出。","集前有雍正甲寅年任启运撰吕从庆传，足资参攷。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9f033536-fc5f-4970-90be-af38f17550de","tags":[]},{"id":"poem-e31e2505584d761a5eea5e67","title":"题竹轩诗","author":"华镇","dynasty":"宋","verses":["岁寒青松青，落落惟修竹。","烟叶舒青翠，风茎戛苍玉。","高标契嘉士，暂挹情已足。","况复清阴中，耽耽有华屋。","屋下富经史，埙篪韵方睦。","啄食日已肥，文彩更繁缛。","侧聆箫韶奏，联翩赴清曲。","秋色正萧疏，庭宇清以肃。","且复遶修林，采采黄金菊。","莫学山阳客，颠倒困醽醁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6a82f225-d50b-4b74-aa73-9f291db6d936","tags":[]},{"id":"poem-e31fbba44c51c7c897b5329c","title":"和段成式 一","author":"周繇","dynasty":"唐","verses":["回簪转黛喜猜防，粉署裁诗助酒狂。","若遇仙丹偕羽化，便随萧史亦何伤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-765d2cc2-4974-4991-91b4-ba2d5e8a173c","tags":[]},{"id":"poem-e321b35c489f4fd355766d57","title":"上林春・一落萦·天惜中秋","author":"晁补之","dynasty":"宋","verses":["天惜中秋，三夜淡云，占得今宵明月。","孟陬岁好，金风气爽，清时挺生贤哲。","相门出相，算锺庆、自应累叶。","乍归来，暂燕处，共仰赤松高辙。","想人生、会须自悦。","浮云事，笑里尊前休说。","旧有衮衣，公归未晚，千岁盛明时节。","命圭相印，看重赏、晋公勋业。","济生灵，共富寿，海山天阔。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-245","tags":[]},{"id":"poem-e32bea91d53fe9528cc7dd84","title":"送三传赴长城尉","author":"张乔","dynasty":"唐","verses":["登科精鲁史，为尉及良时。","高论穷诸国，长才并几司。","地倾流水疾，山叠过云迟。","暇日琴书畔，何人对手棋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3fc457c1-ca13-4a0a-9e61-0154efdb3434","tags":[]},{"id":"poem-e33bc7b3a50cbeb745b9d612","title":"句  其一","author":"宋敏求","dynasty":"宋","verses":["十年情味与君同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-cad5b31a-138f-4f2b-873b-9eca29918cab","tags":[]},{"id":"poem-e33e199e57d5e30269514756","title":"又句","author":"李揆","dynasty":"唐","verses":["共仰新侯伯，同瞻旧宰臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-202c1e80-b368-4fd4-8a57-2069ed80d603","tags":[]},{"id":"poem-e340cf90507a8f377ccdb941","title":"虞美人·庐敖夫妇骖鸾侣","author":"张孝祥","dynasty":"宋","verses":["庐敖夫妇骖鸾侣。","相敬如宾主。","森然兰玉满尊前。","举案齐眉乐事、看年年。","我家白发双垂雪。","已是经年别。","今宵归梦楚江滨。","也学君家儿子、寿吾亲。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-245","tags":[]},{"id":"poem-e34389f75c4a26ea7144f1b3","title":"静女","author":"佚名","dynasty":"先秦","verses":["静女其姝，俟我于城隅。爱而不见，搔首踟蹰。","静女其娈，贻我彤管。彤管有炜，说怿女美。","自牧归荑，洵美且异。匪女之为美，美人之贻。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-41","tags":[]},{"id":"poem-e3452d5fd9995a5561d4d8ee","title":"题王氏志嘉堂二首  其一","author":"李纲","dynasty":"宋","verses":["秀岭云屏拥，湍流玉佩锵。","竹光深锁翠，兰气暗腾芳。","岂谓兵戈日，来登君子堂。","美才方世用，嘉遯自难忘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-842b8a9f-cbfb-4f5d-ad1f-c11b140f96bf","tags":[]},{"id":"poem-e34b43c6acff27b357c6a20e","title":"送江西仓使魏奏院","author":"释居简","dynasty":"宋","verses":["养廉便似挂衣冠，数米晨炊度百囏。","一节易为千里别，万金难售十年闲。","旧从石笋曾招隠，新种梅花试住山。","老去益高华玉价，区区少室谩追攀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4a801884-7e0c-44d7-a479-531a49e1fbd2","tags":[]},{"id":"poem-e350da9bcf988712c2707f6c","title":"明月歌二首  其一","author":"米芾","dynasty":"宋","verses":["高高凝碧夜色卷，八荒更无纤云屯。","冰轮直压巨鼇首，东海万里齐崩奔。","仰观左右毛骨竦，徐扫澄烟摄群动。","寥泬初疑玉兔跳，银潢更恐金波涌。","儿童争指桂枝好，游人不厌嫦娥老。","苦留清景拂疏星，要与羲和接昏晓。","光到长门知不知，犹胜关山人未归。","清风著我生双翼，来作蟾宫变化飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8f69fdea-79ae-4a37-bef8-f19a2703c7dd","tags":[]},{"id":"poem-e3526fa9d41af178c327d0f6","title":"𫠆弁","author":"佚名","dynasty":"先秦","verses":["有𫠆者弁，实维伊何？尔酒既旨，尔肴既嘉。岂伊异人？兄弟匪他。","茑与女萝，施于松柏。未见君子，忧心奕奕；既见君子，庶几说怿。","有𫠆者弁，实维何期？尔酒既旨，尔肴既时。岂伊异人？兄弟具来。","茑与女萝，施于松上。未见君子，忧心怲怲；既见君子，庶几有臧。","有𫠆者弁，实维在首。尔酒既旨，尔肴既阜。岂伊异人？兄弟甥舅。","如彼雨雪，先集维霰。死丧无日，无几相见。乐酒今夕，君子维宴。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-216","tags":[]},{"id":"poem-e35f5e0273de35a63698b762","title":"赋得夏首启节","author":"太宗皇帝","dynasty":"唐","verses":["北阙三春晚，南荣九夏初。","黄莺弄渐变，翠林花落余。","瀑流还响谷，猿啼自应虚。","早荷向心卷，长杨就影舒。","此时欢不极，调轸坐相于。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3850fcde-577f-4a8a-8fae-3efe63b00439","tags":[]},{"id":"poem-e3709b0124ffe568477c8071","title":"临江仙","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生、旦)一十六年不见面，今朝又得再相逢。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8985","tags":[]},{"id":"poem-e386623099a741cccb78fdd6","title":"残丝曲","author":"李贺","dynasty":"唐","verses":["垂杨叶老莺哺儿，残丝欲断黄蜂归。","绿鬓年少金钗客，缥粉壶中沈琥珀。","花台欲暮春辞去，落花起作回风舞。","榆荚相催不知数，沈郎青钱夹城路。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-60f418f1-447d-4916-b885-1cbab41f3bb8","tags":[]},{"id":"poem-e39cfa5b3f79fb208fc0dc0c","title":"书云后三日游致道观","author":"释居简","dynasty":"宋","verses":["九日同游柱史家，野英羞涩未成花。","重来又是书云后，刚德才抽四日芽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-04e7add6-e2df-427c-9f2f-e7d4c5a02190","tags":[]},{"id":"poem-e39debb60c9c19df9df1a5a9","title":"野望","author":"王绩","dynasty":"唐","verses":["东皋薄暮望，徙倚欲何依。","树树皆秋色，山山惟落晖。","牧人驱犊返，猎马带禽归。","相顾无相识，长歌怀采薇。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-野望","tags":[]},{"id":"poem-e3a36b16b08a6ac2b20165e4","title":"杂曲歌辞 独不见","author":"沈佺期","dynasty":"唐","verses":["卢家小妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催下叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁知含愁独不见，使妾明月照流黄。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-15079155-e95e-4abc-b36e-f6b605848f37","tags":["思念","闺怨","唐诗三百首","乐府"]},{"id":"poem-e3ae565440f7345286a69088","title":"送殿中杨监赴蜀见相公","author":"杜甫","dynasty":"唐","verses":["去水绝还波，泄云无定姿。","人生在世间，聚散亦暂时。","离别重相逢，偶然岂定期。","送子清秋暮，风物长年悲。","豪俊贵勋业，邦家频出师。","相公镇梁益，军事无孑遗。","解榻再见今，用才复择谁。","况子已高位，为郡得固辞。","难拒供给费，慎哀渔夺私。","干戈未甚息，纪纲正所持。","泛舟巨石横，登陆草露滋。","山门日易久，当念居者思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9bf99b21-ab26-43d3-aabb-9a06cf6d8953","tags":[]},{"id":"poem-e3b43062869b21ab46a49839","title":"菩萨蛮·回塘起波纹细","author":"李珣","dynasty":"五代","verses":["回塘起波纹细，剌桐花里门斜闭。","残日照平芜，双双飞鹧鸪。","征帆何处客，相见还相隔。","不语欲魂消，望中烟水遥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-43","tags":[]},{"id":"poem-e3b444321e81df8d475ddfa1","title":"龙眠居士画十六大阿罗汉赞  其一三","author":"李纲","dynasty":"宋","verses":["俯身说法，未能忘言。","无量妙义，见于指端。","童子茗供，竹间治具。","涤烦消渴，惟此之故。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-bc881e89-ba25-4eb6-898b-bc839eb15cc6","tags":[]},{"id":"poem-e3b5b47ccc9bdcba0dcb31c6","title":"玉楼春·月皎露华窗影细","author":"顾敻","dynasty":"五代","verses":["月皎露华窗影细，风送菊香沾绣袂。","博山炉冷水沉微，惆怅金闺终日闭。","懒展罗衾垂玉箸，羞对菱花簪宝髻。","良宵好事枉教休，无计那他狂耍婿。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-48","tags":[]},{"id":"poem-e3bf623a5adf01d9740f70bb","title":"读汉纪","author":"徐夤","dynasty":"唐","verses":["布衣空手取中原，劲卒雄师不足论。","楚国八千秦百万，豁开胸臆一时吞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8846f4b5-7891-4fd0-9d83-1a1252e4ca18","tags":[]},{"id":"poem-e3c39d071e6d62da8942002a","title":"横吹曲辞 陇头","author":"张籍","dynasty":"唐","verses":["陇头已断人不行，胡骑夜入凉州城。","汉家处处格鬬死，一朝尽没陇西地。","驱我边人胡中去，散放牛羊食禾黍。","去年中国养子孙，今著毡裘学胡语。","谁能更使李轻车，收取凉州属汉家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bde2cd8e-b62c-4b95-b396-94467a949e6b","tags":[]},{"id":"poem-e3d0d7282f66b6221c58c78f","title":"蝶恋花·翠箔垂云香喷雾","author":"曾觌","dynasty":"宋","verses":["翠箔垂云香喷雾。","年少疏狂，载酒寻芳路。","多少惜花春意绪。","劝人金盏歌金缕。","桃李飘零风景暮。","只有闲愁，不逐流年去。","旧事而今谁共语。","画楼空指行云处。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-370","tags":[]},{"id":"poem-e3d6927b00e6cfa429e01bda","title":"浪淘沙·花外倒金翘","author":"欧阳修","dynasty":"宋","verses":["花外倒金翘。","饮散无憀。","柔桑蔽日柳迷条。","此地年时会一醉，还是春朝。","今日举轻桡。","帆影飘飘。","长亭回首短亭遥。","过尽长亭人更远，特地魂销。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-727","tags":[]},{"id":"poem-e3dbaa30501cfbbac70bd3c1","title":"下第寄友人","author":"马戴","dynasty":"唐","verses":["金门君待问，石室我思归。","圣主尊黄屋，何人荐白衣。","年来御沟柳，赠别雨霏霏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4dfad3ed-9a51-4112-942e-1e84207fdf2c","tags":[]},{"id":"poem-e3dc6ad29034c7b88c170ba7","title":"玉仙馆","author":"张籍","dynasty":"唐","verses":["长溪新雨色如泥，野水阴云尽向西。","楚客天南行渐远，山山树里鹧鸪啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1454d2df-ace5-4fce-8b72-1a5cb201b937","tags":[]},{"id":"poem-e3ddfec19ba17818ef61e4fb","title":"望江南·咏弦月","author":"纳兰性德","dynasty":"清","verses":["初八月，半镜上青霄。","斜倚画阑娇不语，暗移梅影过红桥，裙带北风飘。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-150","tags":[]},{"id":"poem-e3e39467d8290909bcc3373c","title":"春宫曲","author":"王昌龄","dynasty":"唐","verses":["昨夜风开露井桃，未央前殿月轮高。","平阳歌舞新承宠，帘外春寒赐锦袍。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d0fa1454-f337-4343-ab4a-2a42dfdf4e8f","tags":["唐诗三百首","七言绝句","宫怨","女子"]},{"id":"poem-e3ebefcbfbe657808bffdf26","title":"蟋蟀","author":"佚名","dynasty":"先秦","verses":["蟋蟀在堂，岁聿其莫。今我不乐，日月其除。无已大康，职思其居。好乐无荒，良士瞿瞿。","蟋蟀在堂，岁聿其逝。今我不乐，日月其迈。无已大康，职思其外。好乐无荒，良士蹶蹶。","蟋蟀在堂，役车其休。今我不乐，日月其慆。无以大康。职思其忧。好乐无荒，良士休休。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-113","tags":[]},{"id":"poem-e3ee71c63e90165a94d9695d","title":"水月庵","author":"释居简","dynasty":"宋","verses":["心蟾光朣朣，性静湍不起。","悠哉小天地，万化渺无蔕。","清苕半洚水月庵，碧蟾夜夜先清涵。","曩曾借榻坐凉树，细数秋毫闚夜潭。","犹来清圆捉不得，何地容兹老豪逸。","修名与月俱不死，衮衮东流几时息。","乡来万州赋此诗，寥寥百岁无此奇。","诗在天西锦官寺，珠璧照人觉形秽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-191d8885-df94-4d99-a5db-0d55ec60f4aa","tags":[]},{"id":"poem-e3f92673a4d3e0312560bde4","title":"刘母墓","author":"释居简","dynasty":"宋","verses":["怒虎跑云此处传，到今知是几何年。","一弯碧似回珠浦，数曲青藏瘗玉田。","彤管旋添今日史，白华何补乡来篇。","诔辞尽出骚人社，行橐犹能得细诠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-bd1f1a07-05e1-40e1-9962-88e83199dfe8","tags":[]},{"id":"poem-e3fb3705868e60dc702112ef","title":"马诗二十三首 二十","author":"李贺","dynasty":"唐","verses":["重围如燕尾，宝剑似鱼肠。","欲求千里脚，先采眼中光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d7062712-dbd0-414b-a528-36496930d3e1","tags":[]},{"id":"poem-e3fc1c147c6b1f68c2f4abec","title":"山中秋夜","author":"张籍","dynasty":"唐","verses":["寂寂山景静，幽人归去迟。","横琴当月下，压酒及花时。","冷露湿茆屋，暗泉冲竹篱。","西峰采药伴，此夕恨无期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-037532de-b69a-4032-ae4b-63d8b28c101a","tags":[]},{"id":"poem-e3fd8aba08628ea2c2027227","title":"兵要望江南 《周易》占候第二十六（三十七首） 三十六","author":"易静","dynasty":"唐","verses":["四德用，其课我军强。","春占雷巽寅卯木，夏火巳午得离乡，此理要知详（辛本、川本作「当」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cffdcd13-c31f-477b-b726-a32f14215639","tags":[]},{"id":"poem-e41348e01ec38fd30c956425","title":"偈颂（幷序○序为南岳齐己撰） 十三","author":"居遁","dynasty":"唐","verses":["心空不及道空安，道与心空状一般。","参玄不是道空士，一乍相逢不易看。","（又见《祖堂集》卷二十、《景德传灯录》卷二九）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8105bbf2-fdf0-47bd-928d-52d83c263f6e","tags":["衡山"]},{"id":"poem-e41c57a22c010e125952e5c5","title":"和三乡诗","author":"王祝","dynasty":"唐","verses":["女几山前岚气低，佳人留恨此中题。","不知云雨归何处，空使王孙见即迷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b7ae520d-6134-4fb8-9385-702c5c2a2797","tags":[]},{"id":"poem-e427657039c116567ef66927","title":"山阁晚秋","author":"太宗皇帝","dynasty":"唐","verses":["山亭秋色满，岩牖凉风度。","疎兰尚染烟，残菊犹承露。","古石衣新苔，新巢封古树。","历览情无极，咫尺输光暮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5f4f255b-13f1-4a5f-b36c-5ef48f8fc455","tags":[]},{"id":"poem-e428bfcd088aa04ac27376ca","title":"苏君厅观韩干马障歌","author":"顾云","dynasty":"唐","verses":["杜甫歌诗吟不足，可怜曹霸丹青曲。","直言弟子韩干马，画马无骨但有肉。","今日披图见笔迹，始知甫也真凡目。","秦王学士居武功，六印名家声价雄。","乃孙屈迹宁百里，好奇学古有祖风。","竹厅斜日弈碁散，延我直入书斋中。","屹然六幅古屏上，歘见胡人牵入天廐之神龙。","麟鬐凤臆真相似，秋竹惨惨披两耳。","轻匀杏蘂糁皮毛，细撚银丝插騣尾。","思量动步应千里，谁见初离渥洼水。","眼前只欠燕雪飞，蹄下如闻朔风起。","朱崖谪掾从亡殁，更有何人鉴奇物。","当时若遇燕昭王，肯把千金买枯骨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c7a701ec-0276-4364-be88-e02b67c39226","tags":[]},{"id":"poem-e431e67e132ab59eb34b2978","title":"金缕曲·亡妇忌日有感","author":"纳兰性德","dynasty":"清","verses":["此恨何时已。","滴空阶、寒更雨歇，葬花天气。","三载悠悠魂梦杳，是梦久应醒矣。","料也觉、人间无味。","不及夜台尘土隔，冷清清、一片埋愁地。","钗钿约，竟抛弃。","重泉若有双鱼寄。","好知他、年来苦乐，与谁相倚。","我自中宵成转侧，忍听湘弦重理。","待结个、他生知己。","还怕两人俱薄命，再缘悭、剩月零风里。","清泪尽，纸灰起。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-201","tags":[]},{"id":"poem-e43255299b76f7b2691fb916","title":"送长孙九侍御赴武威判官","author":"杜甫","dynasty":"唐","verses":["骢马新凿蹄，银鞍被来好。","绣衣黄白郎，骑向交河道。","问君适万里，取别何草草。","天子忧凉州，严程到须早。","去秋群胡反，不得无电埽。","此行收遗甿，风俗方再造。","族父领元戎，名声国中老。","夺我同官良，飘飖按城堡。","使我不能餐，令我恶怀抱。","若人才思阔，溟涨浸绝岛。","尊前失诗流，塞上得国宝。","皇天悲送远，云雨白浩浩。","东郊尚烽火，朝野色枯槁。","西极柱亦倾，如何正穹昊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-26be693a-2f82-4e8b-be8f-4e14129f185d","tags":[]},{"id":"poem-e436033dd492c5e5ee68f58d","title":"羔裘","author":"佚名","dynasty":"先秦","verses":["羔裘逍遥，狐裘以朝。岂不尔思？劳心忉忉。","羔裘翱翔，狐裘在堂。岂不尔思？我心忧伤。","羔裘如膏，日出有曜。岂不尔思？中心是悼。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-145","tags":[]},{"id":"poem-e443229f944121032252754e","title":"春秋战国门 陈轸","author":"周昙","dynasty":"唐","verses":["丹青徒有逞諠哗，有足由来不是蛇。","杀将破军为柱国，君今官极更何加。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9e4d539b-1165-4d15-8fbd-510ef8bc5e85","tags":[]},{"id":"poem-e44c160912c41cd0bb2b620d","title":"汉武帝将候西王母下降","author":"曹唐","dynasty":"唐","verses":["昆仑凝想最高峰，王母来乘五色龙。","歌听紫鸾犹缥缈，语来青鸟许从容。","风回水落三清月，漏苦霜传五夜钟。","树影悠悠花悄悄，若闻箫管是行踪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-de9fcd28-5e5b-4322-a8fe-ba67cf1c3f90","tags":[]},{"id":"poem-e44c4d61f78be63bfa432a98","title":"宿长水主人","author":"赵嘏","dynasty":"唐","verses":["白云溪北丛岩东，树石夜与潺湲通。","行人一宿翠微月，二十五弦声满风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ec48c8d1-d8ac-488f-b5b6-dc702d74a9cd","tags":[]},{"id":"poem-e44f05b6b691b15a6776c714","title":"郊庙歌辞 周朝飨乐章 忠顺","author":"不详","dynasty":"唐","verses":["岁迎更始，节及朝元。","冕旒仰止，冠劒相连。","八音合奏，万物齐宣。","常陈盛礼，愿永千年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-48f870b0-fa59-43e1-8ef2-6c58dd86f6a3","tags":[]},{"id":"poem-e4500555d8fe4f6fae6f726f","title":"追和柳恽","author":"李贺","dynasty":"唐","verses":["汀洲白苹草，柳恽乘马归。","江头樝树香，岸上蝴蝶飞。","酒杯箬叶露，玉轸蜀桐虚。","朱楼通水陌，沙暖一双鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-285d8546-7dc9-41ef-97ce-fbe35e8bb9c0","tags":[]},{"id":"poem-e4510a6ecfa651f0f9d4c450","title":"狂题十八首 十二","author":"司空图","dynasty":"唐","verses":["来时虽恨失青氊，自见芭蕉几十篇。","应是阿刘还宿债，剩拚才思折供钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-71dac7b3-b68c-42fb-8304-72647303dfe2","tags":[]},{"id":"poem-e45298a9038f15c07b1a05cc","title":"蝴蝶三首 一","author":"徐夤","dynasty":"唐","verses":["不并难飞茧里蛾，有花芳处定经过。","天风相送轻飘去，却笑[蜘蛛]谩织罗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5454a82f-723b-4df9-8c00-057f3d24f305","tags":[]}];
